window.GOHUD_SEARCH["ja"]={"p":["index.html","install.html","ai.html","widgets.html","widgets-catalog.html","widgets-popups.html","widgets-surfaces.html","widgets-messages.html","widgets-hud.html","widgets-feedback.html","widgets-forms.html","widgets-shapes.html","widgets-overlays.html","widgets-style.html","theming.html","theming-presets.html","theming-tokens.html","theming-opacity.html","theming-skins.html","theming-own.html","theming-contrast.html","icons.html"],"n":["概要","インストール","Go HUD Skill","ウィジェット","Widgets-Catalog","Widgets-Popups","Widgets-Surfaces","Widgets-Messages","Widgets-Hud","Widgets-Feedback","Widgets-Forms","Widgets-Shapes","Widgets-Overlays","Widgets-Style","テーマ","Theming-Presets","Theming-Tokens","Theming-Opacity","Theming-Skins","Theming-Own","Theming-Contrast","アイコン"],"d":[[0,"new","新登場：アーケード、コミック、Material 3、キッズ向けの見た目",0,"デフォルト・SF・中世に新しい系統が4つ加わった — 組み込みの見た目は14種類になり、それぞれにダークとライトがある。 どのウィジェット・ポップアップ・HUD 部品も、コードを一切変えずにそのまま受け取る：プリセットを切り替えれば、画面全体がついてくる。 material_light material_dark kids_light kids_dark comic_light comic_dark arcade_light arcade_dark Material 3 — アプリ画面向け 公式の M3 トークンと照らし合わせた Material 3 Expressive だ：48dp のタッチターゲットに 40dp の下地を収めた ピル型ボタン、28dp のダイアログとシート、塗りのカード、アウトラインの入力欄、Expressive のスライダー。アプリ部品 — ナビゲーションバー、アプリバー、FAB、検索バー、チップ、進捗、日付選択 — は M3 のコンポーネントトークンに従い、 タイトルには同梱の Roboto を使う。ショップ、設定、受信箱など、アプリらしく見せたいあらゆる画面に。 キッズ — おもちゃ箱 子どものために作った：キーも行もパネルも、太い縁取りと押すと沈むしっかりした段を持つゼリーキャンディで、 部品の種類ごとに自分のクレヨンの色をまとう。クイックスロットはキャンディのブロック、バッジはステッカー、 スティックは虹色だ。ウィンドウにはお日さま色のタイトルリボンと丸いキャンディの閉じるボタンが付き、押すとぷにっとつぶれる。 サイズとプロジェクトのフォントはまったく変わらない。 コミック — 太いインク どの面もマンガのコマだ：太いインクの輪郭の中に表面の色を塗り、後ろにくっきりした影を落とし、 面を押すとその影が消える。設定1つですべての影をオン・オフし、さらに2つで輪郭の太さと影の大きさを決め、 呼び出し1つで同じことをウィジェット1つにだけ行える。ウィンドウには黄色のタイトルキャプションが付く。 アーケード — 塗られたキー どのキーも塗られている — グラデーション、白い光沢、押すと沈む段を紺色のインクの輪郭に収め — ラベルはインクで縁取った白い文字だ：プレイは緑、ほかは青、削除は赤。ボードは厚く、淡い内側を 色の枠が囲む。ウィンドウには金色のタイトルバナーと丸い赤の閉じるキーが付く。 Material 3 の詳細 → · キッズの詳細 → · アーケードをウィジェットごとに ↓ · コミックをウィジェットごとに ↓ · 同じポップアップを14の見た目で →","GoUi.use_preset(GoThemePresets.MATERIAL_LIGHT) # または MATERIAL_DARK GoUi.use_preset(&\"kids_light\") # または &\"kids_dark\" GoUi.use_preset(&\"comic_light\") # または &\"comic_dark\" GoUi.use_preset(&\"arcade_light\") # または &\"arcade_dark\"",-1],[0,"arcade","アーケード：塗られたキーと厚いボード",0,"いちばん新しい見た目は、どの画面もアーケード筐体のように仕立てる。どのキーも塗られている — 上が明るく下へいくほど 深くなるグラデーション、白い光沢のひと筋、押すと沈む段を、すべて紺色のインクの輪郭に収め — ラベルはインクで縁取った白い文字だ。 どのボードも厚い：自分の光沢を持つ色の枠が、淡い内側を囲む。 arcade_light は空色のページに白いボードを、arcade_dark は夜のページに紺色のボードを置く。 下の画像はすべて本物の gohud の画面だ — 同じコードで、違うのはプリセットの1行だけ。 arcade_light · ギャラリー arcade_dark · ギャラリー GoDialogs GoSheet GoCoachMark GoDrawer GoPopover","GoUi.use_preset(&\"arcade_light\") # または &\"arcade_dark\"",-1],[0,"every-key-painted","どのキーも塗られている",1,"GoStyle.button() GoStyle.tabs() セグメントのキー トグルとチェックボックス GoStyle.card() GoForm GoStyle.choice_grid() GoSlotGrid リストの行 GoDatePicker","",1],[0,"at-night-arcade-dark","夜は arcade_dark",1,"暗いページでは、インクがずっと深くなってページそのものになり、塗りの色は変わらず鮮やかなままだ。 夜の GoStyle.button() GoBar GoStyle.hud_panel() GoSlot GoJoystick アラート GoFab GoRewardCalendar","",1],[0,"how-the-arcade-look-works","アーケードの見た目のしくみ",1,"面 どのキーもボードも GoStyleBoxArcade だ：インクの輪郭、グラデーションの本体、段、光沢を、 コントロール自身の矩形の中に描く — キーは状態が変わっても大きさが変わらず、押すと沈むだけだ。 読めるラベル インクで縁取った白いラベルは、その縁取りが引き離すどんな塗りの上でも読める — WCAG は縁取りを文字の一部として数える。 どの塗りも、グラデーションのどの高さでもラベルが 4.6:1 を超えるまで調整される。 ウィンドウ ウィンドウのタイトルは、インクで縁取った白い文字で金色のバナーに載り、隣に丸い赤の閉じるキーが付く。ダイアログ、 シート、ドロワー、ポップオーバーは厚い枠付きのボードだ。 キー1つに自分だけの色を塗れる — ポーズメニューのオレンジのショップキーのように： アーケードの詳細 → · 同じポップアップを14の見た目で →","menu.add_child(GoStyle.arcade_paint(GoStyle.button(\"Shop\", _shop), Color(\"#FF8A1E\")))",1],[0,"comic","コミック：太いインクとくっきりした影",0,"コミックの見た目は、どの面もマンガのコマのように描く — 太いインクの輪郭の中に表面の色を塗り、 右下へくっきりとしたベタの影を落とす。comic_light は紙のようなクリーム色のページに黒のインクで描き、 プライマリはコバルト。comic_dark は夜のページにクリーム色のインクで描き、プライマリは黄色だ。下の画像はすべて 本物の gohud の画面だ — 同じコードで、違うのはプリセットの1行だけ。 comic_light · ギャラリー comic_dark · ギャラリー GoSheet GoCoachMark GoDrawer GoPopover","GoUi.use_preset(&\"comic_light\") # または &\"comic_dark\"",-1],[0,"every-widget-inked","どのウィジェットもインクで",1,"ボタン、トグル、タブ、スライダー、カード、フォーム、テーブル、ピッカー、チップがみなインクをまとう — 1つずつ スタイルを付ける必要はない。キーを押すと影が消え、面がスタンプのようにその位置へ沈む。 無効な面は影を失って薄くなるので、押せるものと押せないものがひと目で分かる。 GoStyle.button() — すべての種類 トグルとチェックボックス ラジオボタン GoStyle.tabs() セグメントのピル GoStyle.slider() セレクト GoStyle.card() GoForm リストの行 GoTable GoDatePicker GoTimePicker GoStepper フィルターチップ GoNavBar GoInputGroup GoSplitButton GoPagination","",5],[0,"at-night-comic-dark","夜は comic_dark",1,"暗いページでは黒い輪郭が消えてしまうので、comic_dark は輪郭をクリーム色で描き、同じインクの色をおびた 淡い影を落とす。HUD の部品 — クイックスロット、バー、スティック、報酬カレンダー — も同じルールに従う。 夜の GoStyle.button() GoSlot GoBar GoJoystick アラート GoSlotGrid GoRewardCalendar チップ GoRangeSlider GoSearchBar GoFab","",5],[0,"how-the-comic-look-works","コミックの見た目のしくみ",1,"すべての面に1つの StyleBox どの面も GoStyleBoxComic だ：塗り、輪郭、影を、コントロール自身の矩形の内側に描く。描くたびに GoConfig から輪郭と影の大きさを読むので、設定1つで画面全体が一度に変わる。 押すと平らになる 押したキーは影を落とすのをやめ、その位置へ移る。ホバーでは影が残り、フォーカスでは輪郭を決して覆わない内側のインクの輪が加わり、無効な面は影を失って薄くなる。 残りはスキンが描く GoSkinComic は、コードが描くものにインクを入れる：クイックスロット、チップ、バッジ、アバター、通知、ナビゲーションバー、FAB、日付のセル、そしてノブが影を落とすスティック。 ウィンドウにはキャプション ウィンドウのタイトルは、マンガのナレーションの枠のような黄色のキャプションに載り、隣にはインクで描いた丸い閉じるボタンが付く。ダイアログ、シート、ドロワー、ポップオーバーは不透明なインクのパネルだ。 昼も夜も読みやすい どちらのパレットも、ほかのすべてのプリセットと同じ WCAG のコントラスト検査に通る。押したキーや無効なキーも含めてだ。キャプションの色がページに近すぎるときは、その輪郭がページの色に切り替わる。 レイアウトは変わらない 輪郭と影は各コントロールの内側に収まり、内側余白はテーマが与えたままなので、別の見た目でレイアウトした画面はそのままのレイアウトを保つ — プロジェクトのフォントもだ。","",5],[0,"three-settings-and-one-call","設定3つと呼び出し1つ",1,"GoConfig の3つの設定が、すべてのコミックの面を一度に変える。作り直すものは何もない — 値を入れたそばから画面が描き直される。 ウィジェット1つだけなら、設定に関係なく独自の道を行ける。最後の引数に true を渡すと、その中のすべても対象になる。 自分だけのコミックを作る。 tools/new_theme.py inked --from comic_light がパレットをコピーする。紙、 インク、プライマリの色を変えて tools/make_theme.py inked を実行すればいい。インクも影もスキンも一緒についてくる。 コミックの詳細 → · 同じポップアップを14の見た目で →","GoUi.config.comic_border_width = 2.0 # 輪郭 (dp) — 既定は 3 GoUi.config.comic_shadow_size = 6.0 # 影 (dp) — 既定は 4 GoUi.config.comic_shadow = false # どこにも影を出さない GoStyle.comic_shadow(skip_button, false) # このボタンは平らに GoStyle.comic_shadow(card, true, true) # このカードとその中身すべては影を保つ GoStyle.comic_border(title, 5.0) # これだけ輪郭を太く",5],[0,"showcase","ゲーム画面ではこう見える",0,"中世と SF のプリセット — キャラクターシート、インベントリ、クエスト。フォーム、グリッド、 プロンプトカード。角張ったパネルとタッチ操作。プリセットの切り替えはコード1行だ。 中世 — キャラクター・インベントリ・クエスト 中世 — フォーム・グリッド・プロンプトカード SF — 角張ったパネルとタッチ操作 14のプリセットと切り替え方 →","",-1],[0,"what","肩代わりしてくれるもの",0,"ゲーム UI で時間を食うのはボタンの形ではなく、端末ごとにずれていくすべてだ。 gohud はそのずれを1か所で引き受ける。 寸法はすべてトークン 余白・角・文字サイズは数値で書かず名前で呼ぶ。テーマを差し替えれば画面全体がまとめて動く。 見える大きさ ≠ 押せる大きさ 閉じるボタンは 36dp に見えてタッチターゲットは 48dp。スロットが密集して重なる場所は、中心が近いほうが押下を取る。 ノッチとキーボード HUD はセーフエリアの内側に収まり、仮想キーボードが出れば入力欄がその上へ持ち上がる。 戻るは1枚だけ閉じる Escape と Android の戻るは最前面の1枚だけを閉じる。重ねたウィンドウがまとめて消えない。 通知は入力を奪わない スナックバーの上を押しても、その下のボタンが反応する。フォーカスも奪わない。 アイコンは名前で頼む ウィジェットが知っているのは GoIconSet.CLOSE だけ。セットを差し替えればコードに触れずに絵が変わる。 アイコン → 14の見た目、1行 GoUi.use_preset() がテーマ・スキン・アイコンをまとめて入れ替える — 丸み、面取りの SF、鍛造した中世の枠、Material 3 のアプリ部品、キッズのゼリーキャンディ、コミックのインク、アーケードの塗り。 読めるかどうかは測る どのテーマも WCAG で測ってある。ボタンの状態ごとのラベルも、純白・純黒の上に載る半透明 HUD パネルも含めて。 プラグインを有効にしなくても全部動く。 有効にすると GoRuntime オートロードが付いてウィンドウサイズ・ dp 倍率・キーボード高さを追い、設定リソースとプリセットを選ぶプロジェクト設定が増える — 便利なだけで必須ではない。","",-1],[0,"install","gohud をインストール",0,"入口は二つ。AI エージェントに任せるか、フォルダーをプロジェクトに入れるか — ほかに設定するものはない。 インストール","",-1],[0,"start","クイックスタート",0,"五行でテーマの当たった画面が出る。最初から最後までは、インストールのページに。 クイックスタート","",-1],[0,"presets","見た目を変える — 色だけでなく形も",0,"Theme が作り替えられるのはエンジンが描くものだけだ。StyleBoxFlat が持つ角は丸だけで、 スティック・クイックスロット・コーチマークはコードが直接描くため、テーマをいくら替えても形は変わらない。 そこで gohud は、テーマ・スキン・アイコンをひとまとまりで選ぶプリセットを用意している。 プリセット 見た目 default_dark gohud 本来の姿 — 丸い角、やわらかい青のアクセント default_light 同じ形をライトパレットで scifi_dark 面取りした角、シアンのネオン縁と発光、六角形のスティック、照準ブラケット scifi_light 同じ角張った形を明るい設計図のパレットで medieval_dark 暗い鉄と革、アンティークゴールドの枠、リベット、彫刻風アイコン、Cinzel の見出し medieval_light 羊皮紙・インク・青銅に同じ鍛造の枠 material_light 新登場 アプリ画面向けの Material 3 — ピル型ボタン、28dp のダイアログ、塗りのカード、アプリのナビゲーションバー・FAB・検索バー、Roboto material_dark 新登場 同じ Material 3 の形をダークのベースラインで kids_light 新登場 子ども向けのおもちゃ箱 — 太い縁取りと押すと沈む段を持つゼリーキャンディのキー、クレヨンの色、日だまりのように明るいページ kids_dark 新登場 同じおもちゃ箱を夜空色のページで comic_light 新登場 マンガのコマ — どの面にも太いインクの輪郭とくっきりした影、紙のようなクリーム色のページに白いパネル。影、その大きさ、輪郭の太さは設定で変えられる comic_dark 新登場 同じインクを夜のページで — クリーム色の輪郭と黄色のプライマリ arcade_light 新登場 アーケード筐体 — どのキーもグラデーション・光沢・段で塗られ、インクで縁取った白い文字のラベル。空色のページに厚い枠付きのボード、ウィンドウには金色のタイトルバナー arcade_dark 新登場 同じ鮮やかなキーを紺色のボードと夜のページで default_dark — 丸い角、やわらかい青のアクセント default_light — 同じ形、ライトパレット scifi_dark — 面取りの角、シアンのネオン scifi_light — 同じ角張った形、設計図のパレット この4枚は同じギャラリー画面だ。コードは1行も違わず、変えたのはプリセット名だけ。 ボタンの角、トグルの形、リストの行、入力欄の枠が、そろって動いているのが分かる。","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # テーマ・スキン・アイコンがまとめて替わる",-1],[0,"medieval-collection","中世コレクション",1,"medieval_dark は鉄と革にアンティークゴールドを合わせ、medieval_light は羊皮紙とインクを使う。 メニューの枠にはリベットと小さな角飾りを置き、常に見えている HUD は静かなままにした。 彫刻風アイコン16種がアイテム名を描き直し、同梱の Cinzel フォントはタイトルとサブタイトルにだけ使う。 medieval_dark — 鉄と革 medieval_light — 羊皮紙とインク どちらも標準ウィジェットだけで組んだ examples/medieval/medieval.tscn だ。 中世テーマの解説と、自分だけの王国の作り方 →","",14],[0,"the-same-screen-on-a-phone-and-on-a-desktop","同じ画面を、スマートフォンでもデスクトップでも",1,"ギャラリーの4枚は縦持ちのスマートフォンだ。下は同じコードを 1280×800 で開いたもので、本文は読みやすい幅 (480dp) で止まって中央に立ち、HUD は隅に残る。フォームは浮かぶ HUD をよけて回り込むが、 もともと重なっていなければ動かない — 広い画面で無理に押しやると、本文が中心からずれてしまう。 default_dark · 1280×800 scifi_dark · 1280×800","",14],[0,"the-same-sheet-a-different-look","同じシート、違う見た目",1,"デフォルト — 丸いカード、固定された検索行とフッター SF — 上辺のアクセント、切り落とした角、発光 エディタからは プロジェクト設定 → gohud → Theme → Preset で選び、設定リソースからは GoConfig.preset で指定する。theme・skin・icons を明示的に 埋めると、そちらがプリセットより優先される — プリセットを選んだうえで1つだけ差し替えられる。 新しいテーマは JSON ファイル1枚だ。 new_theme.py kingdom --from medieval_dark が、 継承した値をすべて書き出したパレットを作る。make_theme.py kingdom がテーマ・コントロールの絵・ スキンのダイヤルまで生成し、プリセットは選択リストに自動で現れる。設定とダイヤルのすべて →","",14],[0,"skin","スキン — テーマが届かない場所",0,"スキンが受け持つのは、スティック、クイックスロットの面、コーチマークのリング、チップ、スケルトン、 アラート、区切り線、セクション見出しだ。継承して、変えたいものだけを上書きすればよい。 クラス 作れる形 GoStyleBoxCut 角を斜めに切り落とした面取り、1辺だけ太いアクセント縁、外へにじむ発光 GoStyleBoxBracket 中身を囲わず、四隅の印だけを引く GoStyleBoxMedieval リベット・角の彫刻・ベベルのハイライト・素材の質感を持つ鍛造の枠 GoStyleBoxJelly ゼリーキャンディ — 太い縁取り、押すと沈むしっかりした段、上が明るい本体と白いつや GoStyleBoxComic マンガのコマ — 太いインクの輪郭とくっきりしたドロップシャドウ。どちらもゲーム実行中に GoConfig で大きさが決まる GoStyleBoxArcade アーケードのキーやボード — グラデーションの本体、白い光沢、押すと沈む段、インクの輪郭。ボードは淡い内側を厚い色の枠で囲む 6つとも Theme リソースへそのまま保存できる — だからこそテーマが色だけでなく形まで変えられる。 GoSkinSciFi、GoSkinMedieval、GoSkinMaterial、GoSkinKids、GoSkinComic、GoSkinArcade が同梱のサブクラスだ。 スキンが描くもの — デフォルト、キッズ、Material、中世、SF …そしてコミックスキン …そしてアーケードスキン GoStyle.box() は必ず StyleBoxFlat を返す。 呼び出し側が受け取って bg_color や corner_radius を調整するからだ。独自の形を保ったままにしたいときは GoStyle.surface() を使う。","class_name MySkin extends GoSkin func slot_box(accent: Color, lit: bool) -> StyleBox: var box := GoStyleBoxCut.new() box.bg_color = accent box.cut = 6.0 box.edge_color = accent return box",-1],[0,"widgets","ウィジェット",0,"部品を一覧で。ひとつずつ詳しく → · すべてのウィジェットを画像付きで → · ポップアップとダイアログの完全ガイド → クラス 基底 役割 GoSurface Control 浮かぶカードの外殻 — 中央・下・アンカー配置、固定ヘッダーとフッター、スクロール本文、ドラッグでのサイズ変更 GoSheet CanvasLayer 下からせり上がるページ。専用レイヤーを持つので HUD より確実に上に出る GoDialogs Node await で受け取る確認と通知。取り消せない操作には destructive GoForm MarginContainer 幅に上限を設け、仮想キーボードを、avoid_hud なら HUD も避けるフォーム GoScroll ScrollContainer タッチでのスクロール。スクロールバーはカードの余白へ収まる GoNotice PanelContainer 入力もフォーカスも奪わないスナックバー GoPromptCard PanelContainer ゲームを止めずに尋ねるカード GoCoachMark Control 実物のコントロールを指し示すツアー。指した対象を押すと次へ進む GoHudAnchor Control HUD をセーフエリア内の9か所のどれかに留める GoBar Control 体力・マナ・経験値のバー。変化はなめらかに補間される GoSlot Button クイックスロット1つ — アイコン・個数・クールダウン・ショートカットを1つの面に GoJoystick Control 固定・追従・相対モードのバーチャルスティック GoIconButton Button 小さく見えて大きく押せる GoStyle 静的 ボタン、リスト行、入力欄、チップ、表、タブなどを同じ流儀で作る","",-1],[0,"waiting-telling-counting","待たせる、伝える、数える",1,"クラス 基底 役割 GoSnackbar Node 自分で居場所を決めるメッセージ GoSpinner Control 終わりの見えない待ち時間 GoBadge PanelContainer 未読の点、NEW の札、99+","",19],[0,"forms-and-lists","フォームとリスト",1,"クラス 基底 役割 GoField VBoxContainer 間違いを抱えられる行 GoInputGroup HBoxContainer ボタンと溶接された入力欄 GoCombobox Button 検索できるピッカー GoCodeInput VBoxContainer クーポンとギフトコード GoTable VBoxContainer 並べ替えできる見出し、選べる行 GoPagination HBoxContainer ページ番号、あるいは「もっと見る」の行","",19],[0,"shapes-games-actually-use","ゲームで実際に使う形",1,"クラス 基底 役割 GoRewardCalendar VBoxContainer 毎日のログインボーナス GoRadar · GoDonut Control ひと目で分かるステータス GoCarousel VBoxContainer バナーとキャラクター選択 GoKbd HBoxContainer 嘘をつかないキー表示","",19],[0,"over-the-screen","画面の上に重ねる",1,"クラス 基底 役割 GoDrawer CanvasLayer 横から出るパネル GoPopover RefCounted 脇に留まるカード GoContextMenu RefCounted 長押しと右クリック GoConsole CanvasLayer 開発者コンソール","",19],[0,"ai","Go HUD Skill",0,"gohud には AI スキルが入っている — API のすべて、すぐ動くテンプレート、プレビュー起動器。下の文をまるごとコーディングエージェントに貼れば、gohud を入れて使い方まで覚える。 Go HUD Skill","",-1],[0,"readable","読みやすさは目分量ではなく実測で決める",0,"「きれい」は好みだが、「読める」は測れる。 薄い灰色の文字は良いモニタでは平気に見えて、 日中の屋外ではスマートフォンから消える — 目で選んでいれば、いつか必ずそうなる。 すべての色の組み合わせと、ボタンの状態ごとのラベルとその下のパネルを、14のテーマすべてで WCAG に 照らして測る。半透明の色は実際の背景に合成してから測る — そのまま測ると、画面に出ている見え方より 良い比率が出てしまう。 だから文字色は選ぶのではなく導き出す。ビルダーはパレットの値を出発点にして、その文字が載りうる すべての面でしきい値を超えるまで明度を押し上げる。パレットを変えればコントラストも追従する。 その規則と、背後にある落とし穴 → 検査・リリース・このサイト 入口1つですべての検査が走る。それぞれが、ほかからは見えないものを見ている。 検査 捕まえるもの 4つの画面サイズでの run_tests.sh ウィジェットの挙動とレイアウト、RTL での位置、キーボードフォーカス、実行時のスキンのコントラスト、全プリセット new_project_check.sh ホストプロジェクトへの隠れた依存。--zip なら配布物そのまま、--export なら Web ビルドまで check_contrast.py 全テーマファイルの WCAG コントラスト — ボタンの状態も半透明パネルも含めて check_generated.py · check_scaffold.sh 生成されたテーマがパレットと一致するか、使い捨てのテーマが生成できてコントラストを通るか check_package.py package.json のバージョンの反映、変更履歴の移動、ZIP の中身を一時コピー上で check_site.py このサイトのリンク・アンカー・文書言語・用語集・ダイヤル表 直近の記録 — 2026-09-13、Godot 4.7.2、macOS、Compatibility レンダラー。 空のプロジェクトで 390×844・844×390・768×1024・1280×800 の4サイズとも 438/438、GoRuntime オートロードを有効にしても再び 438/438、 Web エクスポート成功、6テーマでコントラスト不足は 0。この実行に Android・iOS の実機は含まれていない。","python3 addons/gohud/tools/check_contrast.py bash addons/gohud/tools/check_all.sh",-1],[0,"release-versions","リリース版を作る",1,"バージョンは package.json に書かれた値で、パッケージングがそれを上げることはない。 新しいバージョンを出すときは、先にその数字を書き換える。 成功すると plugin.cfg・GoUi.VERSION をその値に合わせ、そのバージョンを初めてパッケージングしたときだけ CHANGELOG.md の Unreleased の記述を日付付きの項目へ移す。 同じバージョンでもう一度実行すると ZIP を作り直して前のものと置き換える。失敗すれば何も変わらない。 ZIP にはこのサイトもテストもツールも package.json も入らない。","cat addons/gohud/package.json # { \"version\": \"1.1.0\" } bash addons/gohud/tools/release.sh # 検査すべて → ZIP → 空プロジェクトで検証 bash addons/gohud/tools/package.sh # 1.1.0 → builds/1.1.0/gohud-1.1.0.zip",25],[0,"this-site","このサイト",1,"ページは www/ にあるただの HTML だ — ルートが英語、ko/ が韓国語。 GitHub Actions のワークフローがこのフォルダをサイトのルートとして公開する。","python3 addons/gohud/tools/make_site.py # 用語集とスキンのダイヤル表をソースから生成する python3 addons/gohud/tools/check_site.py # リンク・アンカー・言語・用語集・生成された表を検査する bash addons/gohud/tools/site_shots.sh /tmp/shots # 各ページのデスクトップ幅とスマートフォン幅を撮る",25],[1,"ai-first","いちばん速い道 — AI にインストールを任せる",0,"下の文をそのまま Claude Code・Codex・Cursor・Gemini CLI に貼れば、スキルとアドオンを一緒に入れ、gohud の説明までしてくれる。その道を行くなら、このカードから下は一つも要らない。 Go HUD Skill のページを開く →","",-1],[1,"install","インストール",0,"アドオンのフォルダをプロジェクトに置くだけでよい。ほかに準備はない。","",-1],[1,"from-the-asset-store-or-a-release-zip","アセットストアまたは配布 ZIP から",1,"プロジェクトのルートに展開して res://addons/gohud/ になるようにする。それだけだ。必要なら プロジェクト → プロジェクト設定 → プラグイン → gohud を有効にする。","",29],[1,"as-a-git-submodule","git サブモジュールとして",1,"リポジトリのルートがそのままアドオンのフォルダなので、Godot が期待する場所にぴったり収まる。その場で編集し、 addons/gohud の中でコミットして push したうえで、ゲーム側からサブモジュールのポインタをコミットする。 Godot 4.7 でテストしており、Godot 4.7 以降を公式にサポートする。 gohud は 4.5 で入った API（DPITexture、FoldableContainer、 アクセシビリティ関連プロパティ）を使うため、それより古いエンジンではパース段階で落ちる。 下限の 4.7 は GoUi.MIN_ENGINE に記録してある。","git submodule add https://github.com/thruthesky/gohud.git addons/gohud git submodule update --init git -C addons/gohud checkout v1.0.0 # 任意: タグやコミットに固定する",29],[1,"start","クイックスタート",0,"どのウィジェットも .new() して add_child() するだけだ — シーンファイルもオートロードもいらない。","",-1],[1,"pick-a-look-before-building-ui-optional","UI を組む前に見た目を選ぶ（任意）",1,"","GoUi.use_preset(GoThemePresets.SCIFI_DARK) # 指定しなければ default_dark が使われる",32],[1,"a-confirmation-you-await","await で受け取る確認ダイアログ",1,"最後の引数 destructive を true にすると、確認ボタンが塗りつぶしの危険ボタンとして描かれる。","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"セーブデータの削除\", \"元に戻せません。\"): delete_save()",32],[1,"a-bottom-sheet-with-a-sticky-search-field-and-fo","検索欄とフッターを固定したボトムシート",1,"固定行をスクロール本文と分ける理由。 決定とキャンセルを body に入れると、 リストが長いだけで画面の外へ押し出される。footer() は常に見えている。","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"インベントリ\") sheet.toolbar().add_child(GoStyle.line_edit(\"検索…\")) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, _use.bind(item), Color.TRANSPARENT, item.description, false)) sheet.footer().add_child(GoStyle.button(\"閉じる\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",32],[1,"a-hud-corner","HUD の隅に体力バーを置く",1,"","var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.landscape_spot = GoHudAnchor.Spot.TOP_RIGHT add_child(corner) var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) corner.add_child(hp) hp.set_values(320, 500)",32],[1,"content-that-keeps-clear-of-the-hud","本文が HUD を避けるようにする",1,"失う面積がいちばん小さい方向へ避ける — 縦持ちのスマートフォンでは下へ、横持ちでは横へ。 HUD どうしが避け合うしくみ →","form.avoid_hud = true # 表示中の GoHudAnchor をすべて避ける joystick_anchor.reserve_space = false # …指が触れたときだけ現れるものは除く notice_anchor.avoid_peers = true # トーストは固定 HUD を覆わず、その下に落ち着く",32],[1,"examples","すぐ動かせるサンプル",0,"コードを1行も書かずに gohud を見る3つの方法 — どれもサーバーもオートロードもいらない。 サンプル 開き方 見られるもの ギャラリー examples/gallery/gallery.tscn · F6 すべてのウィジェット、導入済みプリセットの選択リスト、アイコン一式 中世 examples/medieval/medieval.tscn · F6 キャラクターシート、雑嚢、クエストジャーナル。ボタンで鉄と羊皮紙を切り替え、アイテムの詳細を開く デモアプリ cd examples/demo && godot ギャラリー、15章のガイドツアー、ショーケース画面、中世の見た目を開くホーム画面。動くウィジェットと、クラスごとに1枚のカードが載る デモアプリに準備はいらない。アドオンのリンクやインポートキャッシュが欠けていればそう伝えたうえで、フォルダを直して 自分で開き直す。ホーム画面は、それぞれのサンプルを同じウィンドウの中で開く — 1〜4 を押すか行をクリックし、 上端のバーで元へ戻る。 ツアーでは C でシネマモード、F11 で全画面、Space で一時停止（探索中は今のウィジェットを再生）、 矢印キーで章の移動、Escape で開始画面へ戻る。 AI コーディングエージェントを使っているなら 3つとも1コマンドで開ける →","cd examples/demo && godot # ホーム画面。初回はリンクとインポートを済ませる bash examples/demo/run.sh # 同じアプリをアドオンのルートから bash examples/demo/run.sh -- --open=gallery # ホーム画面を飛ばす bash examples/demo/run.sh -- --explore=surfaces # ツアーの1章を直接開く bash examples/demo/run.sh --record /tmp/gohud-demo.avi # ツアーを 1080p / 60fps で録画",-1],[2,"copy","これをコーディングエージェントに貼り付ける",0,"エージェントで Godot プロジェクトを開き、下の文を貼って送る。スキルとアドオンを入れ、gohud で何ができるかまで教えてくれる。 Godot プロジェクトのフォルダーでターミナルを開き、そこでコーディングエージェントを起動する — 例: claude。 下のブロックのコピーを押し、エージェントに貼って送る。 終わったら、求められればエージェントを再起動し、こう聞く: gohud で何ができる？ この文はわざと英語にしてある — どのエージェントもいちばん正確に読む言葉だからだ。質問は何語でもいい。スキルはあなたが書いた言葉で答える。","Install gohud for this Godot 4.7+ project, then use it for all game UI (menus, HUD bars, quick slots, dialogs, bottom sheets, forms, themes). 1. Install the gohud AI skill. Claude Code - run these two commands in a shell: claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud Any other agent (Codex, Cursor, Gemini CLI, ...): git clone --depth 1 https://github.com/thruthesky/gohud.git /tmp/gohud Copy /tmp/gohud/skills/gohud into whichever of these folders this agent reads: ~/.claude/skills/gohud, .claude/skills/gohud, .agents/skills/gohud. 2. Install the add-on itself, unless addons/gohud/plugin.cfg already exists here. In a git repository: git submodule add https://github.com/thruthesky/gohud.git addons/gohud Otherwise copy the clone to addons/gohud without its .git folder. Then run: godot --headless --path . --import (If godot is not on PATH, ask me where Godot 4.7+ is.) 3. Check the result: addons/gohud/plugin.cfg exists and the import printed no \"SCRIPT ERROR\" or \"Parse Error\" lines. 4. A new skill loads when the agent starts. Tell me if I have to restart you, then tell me what gohud can do and how to preview it. Docs: https://thruthesky.github.io/gohud/",-1],[2,"claude-code","またはコマンド 2 行 — Claude Code",0,"スキルを Claude Code のプラグインとして入れる。ターミナルで: すでに Claude Code の中なら、こちらを打つ: それから Claude Code を再起動して /gohud:features と打つ — gohud の機能一覧が出ればスキルは入っている。アドオン本体は別に addons/gohud に要る: インストール →","claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud /plugin marketplace add thruthesky/gohud /plugin install gohud@gohud",-1],[2,"agents","エージェントごとのスキル置き場",0,"手で入れるなら skills/gohud フォルダーをエージェントが読む場所に置く。先にあるものが使われる。 エージェント フォルダーを置く場所 コマンドの形 Claude Code — プラグイン claude plugin install gohud@gohud /gohud:preview · /gohud:features Claude Code — スキルのみ ~/.claude/skills/gohud /gohud preview · /gohud features Claude Code — このプロジェクトだけ .claude/skills/gohud /gohud preview Codex · Cursor · Gemini CLI — その他 .agents/skills/gohud —","",-1],[2,"commands","使えるようになるコマンド",0,"","",-1],[2,"gohud-preview-the-widget-gallery","/gohud:preview — ウィジェットギャラリー",1,"ギャラリーを開く。すべてのウィジェット、すべてのプリセットの選択リスト、アイコン一式が入っている。自分の Godot プロジェクトの中で打てばそのプロジェクトの addons/gohud を使い、無ければプラグイン同梱の コピーか、新しくクローンしたものを使う。使い捨てのサンドボックスプロジェクトで動くので、自分のオートロードや インポートキャッシュには触れず、ウィンドウは閉じるまで開いたままだ。","",42],[2,"gohud-preview-demo-the-19-chapter-guided-tour","/gohud:preview demo — 15章のガイドツアー",1,"デモを開始画面で開く。Start demo は実際の入力でツアーを再生し、Explore widgets は ウィジェット1つを手で試させる。サンプルに挙げたキー操作はここでも同じだ。","",42],[2,"many-other-commands","ほかにも多くのコマンドがある",1,"コマンド 役割 /gohud:preview medieval 中世プリセットのキャラクターシート・雑嚢・クエストジャーナル /gohud:preview demo --explore hud デモを1章だけ直接開く — hud buttons inputs selection lists data states surfaces prompt touch coach scrolling forms anchors theming /gohud:preview gallery --preset scifi_dark プリセット1つを当てたギャラリー。--phone で 390×844 のスマートフォン窓、--size 1920x1080 で任意のサイズ /gohud:preview res://ui/main_menu.tscn 自分のプロジェクトのシーンを、そのプロジェクトの中で実行する /gohud:preview list 開ける対象・プリセット id・デモの章キーの一覧 /gohud:preview gallery --check ウィンドウを出さないヘッドレス点検 — スクリプトエラーがあれば失敗する /gohud:features 機能を分類ごとに、1機能あたりコード1行で /gohud:features hud 1つの分野を深く — surfaces hud style theming icons i18n accessibility config プレビューのコマンドには PATH に Godot 4.7 以上が要る。","",42],[2,"ask","ふつうに頼んでもいい",0,"そのまま頼んでもよい。 スキルがエージェントに gohud の API 全体を教えるので、 「gohud でポーズメニューを作って」のような普通の依頼も通る。プラグインではなく素のスキルとして ~/.claude/skills/gohud に置いた場合はコマンドを空白で区切る — /gohud preview demo、 /gohud features。プレビューには PATH の通った Godot 4.7 以降が必要で、 無ければ --godot /path/to/godot で渡す。","",-1],[4,"layout","レイアウト (15)",0,"GoScaffold アプリ画面を一度に組み立てる — バー、スクロールするページ、下部バー、FAB、ドロワー。 継承 Control GoTopBar 上端に沿って 1～3 個の枠。中央の枠は常に中央。 継承 GoEdgeBar GoBottomBar 下端に沿って配置。ジェスチャーバーを避ける。 継承 GoEdgeBar GoLeftSideBar 左端に沿って最大 3 段。 継承 GoSideBar GoRightSideBar 右端に沿って最大 3 段。 継承 GoSideBar GoSideBar 上の二つの元になるサイドバー。右から左の言語でも位置を変えない。 継承 GoEdgeBar GoEdgeBar すべての端バーに共通の規則 — 枠、均等配置、端への固定、セーフエリア。 継承 Container GoGrid 幅がぴったり等しい列 — 決まった数、または入るだけ。 継承 Container GoForm 幅を抑え、キーボードと HUD を避けるフォーム。 継承 MarginContainer GoScroll 内容のどこからでも効くタッチスクロール。右から左の言語にも対応。 継承 ScrollContainer GoHudAnchor HUD の部品をセーフエリアの 9 か所のどれかに固定する。 継承 Control GoStyle.column · row · wrap_row テーマの間隔を使う縦並び・横並び・折り返し行。 所属 GoStyle GoStyle.responsive_grid · aspect 広がると列が増えるグリッドと、比率を保つ箱。 所属 GoStyle GoStyle.padding · spacer · divider 内側の余白、余った幅を埋めるスペーサー、区切り線。 所属 GoStyle GoStyle.foldable · section 節見出しと、開閉できる節。 所属 GoStyle","var page := GoStyle.column() var screen := GoScaffold.make(\"Inbox\", page, true) screen.set_fab(GoFab.make(GoIconSet.EDIT)) add_child(screen) var bar := GoTopBar.make(3) bar.add_start(GoStyle.icon_button(GoIconSet.BACK, go_back, -1, &\"back\")) bar.add_center(GoStyle.label(\"Stage 3\")) bar.add_end(GoStyle.chip(\"1,250\")) var actions := GoBottomBar.make(1, GoBottomBar.Justify.SPACE_BETWEEN) for name in [\"Attack\", \"Guard\", \"Run\"]: actions.add_start(GoStyle.button(name)) screen.add_child(actions) var tools := GoLeftSideBar.make(3) tools.add_start(GoStyle.icon_button(GoIconSet.MENU, open_menu, -1, &\"menu\")) tools.add_end(GoStyle.icon_button(GoIconSet.USER, open_profile, -1, &\"profile\")) screen.add_child(tools) var tools := GoRightSideBar.make(3) tools.add_start(GoStyle.icon_button(GoIconSet.SETTINGS, open_settings, -1, &\"settings\")) tools.add_center(GoStyle.icon_button(GoIconSet.SEARCH, find, -1, &\"search\")) screen.add_child(tools) var rail := GoRightSideBar.make(1, GoSideBar.Justify.CENTER) rail.add_start(GoStyle.icon_button(GoIconSet.MAP, open_map, -1, &\"map\")) var bar := GoTopBar.make(1) bar.justify = GoEdgeBar.Justify.SPACE_BETWEEN bar.pin_to_edge = GoEdgeBar.Pin.ALWAYS var cards := GoGrid.make(1, 160.0) for item in items: cards.add_child(GoStyle.item_card(item)) var form := GoForm.new() form.avoid_hud = true form.add_child(GoScroll.new()) add_child(form) var list := GoScroll.new() list.add_child(GoStyle.column()) var strip := GoScroll.horizontal() var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.add_child(GoStyle.hud_panel()) var page := GoStyle.column() var line := GoStyle.row() var chips := GoStyle.wrap_row() var tiles := GoStyle.responsive_grid(160) var thumb := GoStyle.aspect(16.0 / 9.0) var pad := GoStyle.padding(16) line.add_child(GoStyle.spacer()) page.add_child(GoStyle.divider()) page.add_child(GoStyle.section(\"Sound\", false)) var more := GoStyle.foldable(\"Advanced\", true, null, false)",-1],[4,"windows","ウィンドウとオーバーレイ (9)",0,"GoSurface 浮かぶウィンドウ — 中央、下から、またはコントロールの横に。 継承 Control GoSheet ページ、戻る操作、固定フッターを持つボトムシート。 継承 CanvasLayer GoDialogs await で待つ確認・お知らせウィンドウ。お知らせは順番を待つ。 継承 Node GoDialogs.choose いくつかから一つ — スマホでは下からのシート、デスクトップではカード。 所属 GoDialogs GoDrawer 左または右から滑り込むパネル。 継承 CanvasLayer GoPopover 押したものの横に出る情報カード。一度に一つ。 継承 RefCounted GoContextMenu 長押し・右クリックのメニュー。指が動くと取り消される。 継承 RefCounted GoCoachMark 実際のコントロールを指し示すガイドツアー。 継承 Control GoConsole コマンドと履歴を持つ開発者コンソール。リリースビルドでは無効。 継承 CanvasLayer","var window := GoSurface.new() window.set_title(\"Settings\") window.close_requested.connect(window.queue_free) layer.add_child(window) var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Inventory\") sheet.body.add_child(bag_list) var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Delete save\", \"This cannot be undone.\", \"\", \"\", \"\", {}, true): delete_save() var index := await dialogs.choose(\"Sort by\", [\"Newest\", \"Price\", \"Rating\"]) if index >= 0: sort_by(index) var drawer := GoDrawer.new() add_child(drawer) drawer.side = GoDrawer.Side.RIGHT drawer.open(\"Bag\") GoPopover.open(slot, GoStyle.item_card(item, false)) GoContextMenu.attach(slot, [{\"text\": \"Use\"}, {\"text\": \"Drop\", \"danger\": true}]) var tour := GoCoachMark.new() add_child(tour) tour.start([{\"target\": bag_button, \"title\": \"Bag\", \"body\": \"Your items live here.\"}]) var console := GoConsole.new() add_child(console) console.register(\"give\", \"Grant an item\", give_item)",-1],[4,"messages","メッセージと待機 (12)",0,"GoSnackbar 下に出るメッセージ。順番待ちし、ボタンも付けられる。 継承 Node GoNotice 入力もフォーカスも奪わないお知らせ。 継承 PanelContainer GoPromptCard ゲームを止めない問いかけ — 招待、取引。 継承 PanelContainer GoBanner 対処されるまでページに残るメッセージ。 継承 PanelContainer GoSpinner 待機表示。ボタンをその場でスピナーに変え、二度押しを防ぐ。 継承 Control GoBadge 未読の点、NEW タグ、99+ を角に付ける。 継承 PanelContainer GoProgress 線か輪で示す進捗。波形か平坦、量が不明なら不確定表示。 継承 Control GoLoadingIndicator 形が変わる Material 3 Expressive の待機マーク。reduce_motion では止まる。 継承 Control GoRefresh リストの一番上で下に引いて再読み込み。 継承 Control GoStyle.alert 情報・成功・注意・危険の色調のインラインメッセージ。 所属 GoStyle GoStyle.skeleton · empty_state 読み込み中のプレースホルダーと、空のリストの案内。 所属 GoStyle GoStyle.tooltip_node テーマの見た目のツールチップ。単語を割らない。 所属 GoStyle","var snack := GoSnackbar.new() add_child(snack) if await snack.post({\"text\": \"Item dropped\", \"actions\": [\"Undo\"]}) == 0: restore_item() var notice := GoNotice.new() hud.add_child(notice) notice.show_text(\"Saved\", GoTheme.SUCCESS) var invite := GoPromptCard.new() invite.set_title(\"Party invite from Ann\") invite.set_actions([{\"text\": \"Accept\", \"action\": accept, \"primary\": true}]) var offline := GoBanner.make(\"You're offline.\", [{\"text\": \"Retry\", \"action\": reconnect}], GoIconSet.WARNING) page.add_child(offline) GoSpinner.busy(buy_button, true) await shop.buy(item) GoSpinner.busy(buy_button, false) GoBadge.attach(mail_button, unread) GoBadge.attach(shop_button, 0, \"NEW\") var upload := GoProgress.linear() upload.value = 0.4 var ring := GoProgress.circular(true) var wait := GoLoadingIndicator.new() wait.contained = true page.add_child(wait) var refresh := GoRefresh.attach(feed) refresh.refresh_requested.connect(func() -> void: await reload_posts() refresh.finish()) page.add_child(GoStyle.alert(\"Maintenance at 3 AM\", GoTheme.WARNING)) page.add_child(GoStyle.skeleton(200)) page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"No items yet\", false)) func _make_custom_tooltip(text: String) -> Object: return GoStyle.tooltip_node(text)",-1],[4,"navigation","アプリのナビゲーション (13)",0,"GoAppBar 上部のアプリバー。ページがスクロールすると浮き上がり、中・大の見出しも可能。 継承 PanelContainer GoNavBar 下部に 3～5 個の行き先。広い画面ではレール。 継承 PanelContainer GoNavBar.drawer_list ドロワー用の全幅の行き先の行。 所属 GoNavBar GoFab 隅に浮かぶ画面の主操作。40～96dp、またはラベル付きの拡張型。 継承 Button GoSearchBar クリアボタンと末尾の操作を持つ丸い検索欄。 継承 PanelContainer GoSplitButton 主操作と、矢印の奥にあるその変形。 継承 HBoxContainer GoTabView 行いっぱいのタブと、スワイプで移るページ。 継承 VBoxContainer GoStyle.tabs タブ列。先頭に寄せるか行いっぱいに広げる。下線は端まで続く。 所属 GoStyle GoStyle.bottom_app_bar アイコン操作と FAB を持つ下部バー。 所属 GoStyle GoStyle.toolbar アイコン操作をまとめた浮かぶピル。 所属 GoStyle GoStyle.breadcrumb 現在地を、さかのぼれる経路として。 所属 GoStyle GoPagination 現在のページを中央に保つ番号付きページ、または「もっと見る」1 行。 継承 HBoxContainer GoCarousel バナーとキャラクター選択。頼まれない限り勝手にめくれない。 継承 VBoxContainer","var bar := GoAppBar.make(\"Inbox\", GoIconSet.MENU, open_drawer) bar.add_action(GoIconSet.SEARCH, &\"search\", open_search) bar.follow(list) var nav := GoNavBar.make([{\"icon\": GoIconSet.HOME, \"text\": \"Home\"}, {\"icon\": GoIconSet.BELL, \"text\": \"Alerts\", \"badge\": 3}], 0, show_tab) var rail := GoNavBar.rail([{\"icon\": GoIconSet.HOME, \"text\": \"Home\"}]) drawer.body.add_child(GoNavBar.drawer_list([{\"icon\": GoIconSet.HOME, \"text\": \"Inbox\"}, {\"icon\": GoIconSet.STAR, \"text\": \"Starred\"}], 0, go_to)) var cart := GoFab.make(GoIconSet.PLUS, \"Add to cart\", add_to_cart) cart.float_in(self, nav.get_combined_minimum_size().y) var search := GoSearchBar.make(\"Search products\", find) search.add_action(GoIconSet.FILTER, &\"Filter\", open_filters) var send := GoSplitButton.make(\"Send\", send_now, [\"Send later\", \"Save as draft\"]) send.chosen.connect(func(index: int) -> void: send_variant(index)) var tabs := GoTabView.make([\"Posts\", \"Photos\", \"Saved\"], [posts, photos, saved]) tabs.tab_changed.connect(func(index: int) -> void: track_tab(index)) var row := GoStyle.tabs([\"Overview\", \"Stats\", \"Gear\"], 0, false, true) row.tab_changed.connect(show_panel) screen.set_bottom_bar(GoStyle.bottom_app_bar([{\"icon\": GoIconSet.SEARCH, \"tooltip\": &\"search\"}, {\"icon\": GoIconSet.HEART, \"tooltip\": &\"Like\"}], GoFab.make(GoIconSet.PLUS))) page.add_child(GoStyle.toolbar([{\"icon\": GoIconSet.EDIT, \"tooltip\": &\"Edit\", \"action\": edit}, {\"icon\": GoIconSet.TRASH, \"tooltip\": &\"Delete\", \"action\": delete}])) page.add_child(GoStyle.breadcrumb([\"Home\", \"Shop\", \"Swords\"], go_to_level)) var pages := GoPagination.make(1, 12, load_page) page.add_child(pages) var banners := GoCarousel.new() banners.set_pages([promo, event, pack])",-1],[4,"buttons","ボタン・チップ・選択 (9)",0,"GoStyle.button 7 種類の色調のボタン — 通常、主要、アウトライン、テキスト、小型、危険、塗りつぶし危険。 所属 GoStyle GoStyle.glow 塗りつぶしボタンを光で浮かせる。 所属 GoStyle GoIconButton アイコンだけのボタン。見た目は小さく、押せる範囲は 48dp、読み上げ用の名前付き。 継承 Button GoStyle.chip 文字が必ず読める状態・タグのピル。 所属 GoStyle GoStyle.filter_chip · input_chip オン・オフするチップと、✕ 付きの入力値。 所属 GoStyle GoStyle.segmented いくつかからちょうど一つ。一列につなげる。 所属 GoStyle GoStyle.choice_grid グリッドから見本を一つ — 色、スキン — 選ぶ。 所属 GoStyle GoStyle.radio_group 一つだけ選ぶラジオボタン。 所属 GoStyle GoStyle.toggle · checkbox ラベル付きのスイッチとチェックボックス。 所属 GoStyle","row.add_child(GoStyle.button(\"Play\", play, GoStyle.Tone.PRIMARY)) row.add_child(GoStyle.button(\"Details\", open_details, GoStyle.Tone.OUTLINED)) row.add_child(GoStyle.button(\"Skip\", skip, GoStyle.Tone.BARE)) row.add_child(GoStyle.glow(GoStyle.button(\"Play\", play, GoStyle.Tone.PRIMARY))) row.add_child(GoStyle.icon_button(GoIconSet.CLOSE, close, -1, &\"close\")) var bell := GoIconButton.new() bell.icon_name = GoIconSet.BELL row.add_child(GoStyle.chip(\"Rare\", GoUi.color(GoTheme.INFO))) filters.add_child(GoStyle.filter_chip(\"In stock\", false, refilter)) to.add_child(GoStyle.input_chip(\"Ann\", remove_ann, GoIconSet.USER)) page.add_child(GoStyle.segmented([\"Day\", \"Week\", \"Month\"], 0, show_range)) var skins := GoStyle.choice_grid([{\"color\": \"f6cfae\", \"tooltip\": \"Peach\"}, {\"color\": \"8d5a36\", \"tooltip\": \"Cocoa\"}], 0, pick_skin) page.add_child(GoStyle.radio_group([\"Easy\", \"Normal\", \"Hard\"], 1)) var music := GoStyle.toggle(\"Music\", false) var terms := GoStyle.checkbox(\"I agree to the terms\", false)",-1],[4,"inputs","入力とピッカー (12)",0,"GoStyle.line_edit · textarea 一行と複数行のテキスト欄。 所属 GoStyle GoField ラベル・コントロール・ヒント。誤った欄の下にエラーを出す。 継承 VBoxContainer GoInputGroup 入力欄とそのボタンを一つの形に溶接する。 継承 HBoxContainer GoCombobox 名前の先頭だけでなく中まで探す選択欄。 継承 Button GoCodeInput マスで表示するクーポン・ギフトコード。貼り付けと IME 入力もそのまま使える。 継承 VBoxContainer GoStyle.select · dropdown ドロップダウンリストと、メニューを開くボタン。 所属 GoStyle GoStyle.slider テーマの形のスライダー。 所属 GoStyle GoRangeSlider 交差しない 2 つのつまみ — 価格やレベルの範囲。 継承 Control GoDatePicker タップで選ぶ 1 か月。range_mode で期間も。 継承 Container GoTimePicker 時計の文字盤。時の次に分、12・24 時間、枠で上下キー。 継承 Container GoWheelPicker 回って帯の上に一項目を止めるホイール。 継承 Control GoStepper 「次へ」「戻る」付きの番号ステップ。縦並びか一列で。 継承 VBoxContainer","var nickname := GoStyle.line_edit(\"Your name\") var note := GoStyle.textarea(\"Message\", 4) var field := GoField.make(\"Nickname\", GoStyle.line_edit(), \"3–12 letters\", false) field.set_error(\"That name is taken\") var chat := GoInputGroup.make(GoStyle.line_edit(\"Message\"), {\"suffix\": GoStyle.button(\"Send\", send)}) var friend := GoCombobox.make(friends, -1, \"Find a friend\") friend.picked.connect(invite) var coupon := GoCodeInput.make(12, 4) coupon.completed.connect(redeem) var quality := GoStyle.select([\"Low\", \"Medium\", \"High\"]) var sort := GoStyle.dropdown(\"Sort\", [\"Newest\", \"Price\"], sort_by) var volume := GoStyle.slider(0.0, 1.0, 0.05) volume.value_changed.connect(set_volume) var price := GoRangeSlider.make(0.0, 500.0, 40.0, 220.0, 10.0) price.change_ended.connect(func(low: float, high: float) -> void: refilter(low, high)) var stay := GoDatePicker.make() stay.range_mode = true stay.range_picked.connect(func(start: Dictionary, end: Dictionary) -> void: book(start, end)) var alarm := GoTimePicker.make(7, 30, func(hour: int, minute: int) -> void: set_alarm(hour, minute)) alarm.use_24h = true var amount := GoWheelPicker.make([\"x1\", \"x5\", \"x10\", \"x50\"], 0, set_amount) row.add_child(amount) var checkout := GoStepper.make([{\"title\": \"Cart\", \"content\": cart}, {\"title\": \"Pay\", \"content\": pay}]) checkout.finished.connect(place_order)",-1],[4,"lists","リスト・カード・データ (8)",0,"GoStyle.list_row · list_button アイコン・タイトル・概要・末尾マークを持つリスト行。 所属 GoStyle GoListView 数千行でも、見えている行だけを作る。 継承 GoScroll GoReorderList つまみか長押しでドラッグして並べ替える行。 継承 Container GoSwipeRow 横にスワイプして削除・保管する行。リストのスクロールはそのまま。 継承 Container GoTable 並べ替えできる見出しと選べる行。数値は数値として並ぶ。 継承 VBoxContainer GoStyle.card · item_card カードと、選んだアイテムの詳細カード。 所属 GoStyle GoStyle.avatar 円の中のイニシャルか画像。 所属 GoStyle GoStyle.label マイクロから見出しまで 7 種類の文字の役割から一つで。 所属 GoStyle","page.add_child(GoStyle.list_button(GoIconSet.SETTINGS, \"Settings\", open_settings, Color.TRANSPARENT, \"\", false)) var feed := GoListView.make(10000, 72.0, func(index: int) -> Control: return post_row(posts[index])) feed.end_reached.connect(load_more) var queue := GoReorderList.make([intro_row, theme_row, boss_row]) queue.reordered.connect(func(from: int, to: int) -> void: songs.insert(to, songs.pop_at(from))) inbox.add_child(GoSwipeRow.wrap(mail_row, {\"icon\": GoIconSet.TRASH, \"text\": \"Delete\", \"tone\": GoTheme.DANGER, \"action\": delete_mail})) var board := GoTable.make([\"Name\", {\"text\": \"Score\", \"numeric\": true}], [[\"Ann\", 9124], [\"Ben\", 91240]]) board.row_selected.connect(open_profile) var card := GoStyle.card() card.add_child(GoStyle.label(\"Daily quest\")) popup.add_child(GoStyle.item_card({\"title\": \"Rusty sword\", \"subtitle\": \"Common\"})) row.add_child(GoStyle.avatar(\"AK\", 40)) page.add_child(GoStyle.label(\"Level 12\", GoTheme.ROLE_TITLE)) page.add_child(GoStyle.label(\"Next level in 340 XP\", GoTheme.ROLE_CAPTION, GoUi.color(GoTheme.MUTED)))",-1],[4,"hud","HUD とゲームの形 (11)",0,"GoBar 値・分数・パーセントを表示する HP・MP・XP バー。 継承 Control GoSlot クイックスロット。アイコン・数量・クールダウン・ショートカットを一面に。 継承 Button GoSlotGrid インベントリのグリッド。マス間でアイテムをドラッグできる。 継承 HFlowContainer GoJoystick 仮想スティック — 固定、親指に追従、相対。 継承 Control GoKbd 実際の割り当てを読むキーキャップ。割り当てを変えても案内が嘘にならない。 継承 HBoxContainer GoChoiceColumn 一度タップで選ぶ短い縦リスト — 召喚リスト。ゲームが何行でも印を付けられる。 継承 Control GoRewardCalendar 毎日の出席報酬。押せるのは今日だけ。 継承 VBoxContainer GoRadar ステータスの五角形。装備の比較は点線で。 継承 Control GoDonut 割合を扇形で。凡例は色だけでなく言葉でも。 継承 Control GoZoomView 地図をピンチ・ホイール・ダブルタップで拡大。端の内側で移動。 継承 Control GoStyle.hud_panel · overlay_panel ゲームの上に浮かぶパネル。どんな絵の上でも文字が読める。 所属 GoStyle","var hp := GoBar.new() hp.label_text = \"HP\" hp.set_values(320, 500) var potion := GoSlot.new() potion.icon_name = GoIconSet.POTION potion.quantity = 12 potion.start_cooldown(5.0) var bag := GoSlotGrid.new() bag.set_cell(0, {\"icon\": GoIconSet.POTION, \"quantity\": 12}) var pad := GoJoystick.new() pad.mode = GoJoystick.Mode.FOLLOW pad.moved.connect(func(direction: Vector2) -> void: player.move(direction)) hint.add_child(GoKbd.for_action(&\"interact\")) var animals := GoChoiceColumn.make([\"Hen\", \"Cat\", \"Dog\", \"Pig\", \"Cow\"], 4, summon) animals.set_selected(2, true) side_bar.add_center(animals) var attendance := GoRewardCalendar.make(days, claimed_until) attendance.claimed.connect(func(day: int) -> void: server.claim_day(day)) var stats := GoRadar.make({\"STR\": 0.85, \"AGI\": 0.5, \"INT\": 0.3, \"VIT\": 0.7, \"LUK\": 0.45}) stats.set_compare(with_new_sword) var share := GoDonut.make([{\"label\": \"Physical\", \"value\": 620}, {\"label\": \"Magic\", \"value\": 340}]) card.add_child(share.legend()) var map := GoZoomView.wrap(world_map, 4.0) map.custom_minimum_size.y = 320 page.add_child(map) var bars := GoStyle.hud_panel() var pill := GoStyle.overlay_panel()",-1],[4,"look","見た目とシステム (8)",0,"GoUi · GoThemePresets プリセット（デフォルト・SF・中世・Material・キッズ・コミック・アーケード）から選び、色とサイズはトークンから読む。 継承 RefCounted GoConfig すべての設定を入れる一つのリソース。アドオンを更新しても残る。 継承 Resource GoSkin コードが描く形 — チップ、スロット、ジョイスティック、新しい部品 — を自分の流儀で。 継承 Resource GoIconSet · GoGameIcons 名前で呼ぶアイコン — 標準セット、ゲームアイコン 187 個、または自分の SVG。 継承 Resource · RefCounted GoStyleBoxCut · GoStyleBoxBracket · GoStyleBoxMedieval 自分のパネルに使える面取り・括弧・鍛造の面。 継承 StyleBox GoSafeArea · GoScale ノッチ・ジェスチャーバー・キーボードを避けた領域と、dp 基準のブレークポイント。 継承 Control · RefCounted GoFeedback 効果音の合図と振動を自分のオーディオへ送る。gohud は音を同梱しない。 継承 RefCounted GoBackPolicy いま Android の戻ると Esc を持つのは誰か。ウィンドウ間で共有する。 継承 RefCounted","GoUi.use_preset(GoThemePresets.MATERIAL_LIGHT) var accent := GoUi.color(GoTheme.ACCENT) var gap := GoUi.metric(GoTheme.GAP) GoUi.config.reduce_motion = true GoUi.config.container_alpha = 1.0 GoUi.refresh() class_name MySkin extends GoSkin func banner_box() -> StyleBox: return surface_box(GoTheme.BOX_CARD) GoUi.config.icons = GoGameIcons.icon_set() var gear := GoUi.icons().node(GoIconSet.SETTINGS, 24) var face := GoStyleBoxCut.new() face.cut = 8 panel.add_theme_stylebox_override(&\"panel\", face) var usable := GoSafeArea.usable_rect(get_window()) var size_class := GoScale.breakpoint_for_dp(minf(usable.size.x, usable.size.y)) # by the short side GoFeedback.sound_handler = func(cue: String) -> void: audio.play_cue(cue) GoFeedback.haptic_handler = func(ms: int, amplitude: float) -> void: Input.vibrate_handheld(ms, amplitude) GoBackPolicy.acquire(get_tree())",-1],[5,"popup-map","ふさわしいポップアップを選ぶ",0,"ポップアップは流れを断ち切る。選ぶ前に、ひとつの問いにだけ答える：ゲームが先へ進む前に、プレイヤーが 必ず答えなければならないか？ そうなら塞ぐ。そうでないなら決して塞がない — 頼んでもいない知らせでゲームを止める カードは、プレイヤーにゲームを閉じさせるいちばんの近道だ。 答えのある問い — 購入、削除、退出、上書き → GoDialogs.confirm()。確認してもらうだけのこと → alert()。いくつかから1つ → choose()。 それ自体が1つの画面 — 設定、キャラクターシート、ショップのアイテム → 画面中央の GoSurface。 長いリストや管理画面 — かばん、メール、フレンド → スマホでは下から出る GoSheet、広い画面では横から出る GoDrawer。 今押したものについての情報 — アイテムのステータス、できる操作 → その脇に出る GoPopover か GoContextMenu。 ゲームを止めずに伝えられる知らせ — 保存した、捨てた、招待された → GoSnackbar、GoNotice、GoPromptCard。これらは画面を占領しない。 操作を教える → GoCoachMark。開発中のチート → GoConsole。","",-1],[5,"every-popup-at-a-glance","すべてのポップアップを一覧で",1,"ポップアップ ゲームを止めるか 戻る / Escape 外側のタップ 用途 GoDialogs confirm · alert はい 閉じる — confirm は false を返し、alert は await が終わる dismiss_on_scrim のときだけ閉じる 答えが必要な問い GoDialogs.choose はい 閉じる — -1 を返す dismiss_on_scrim のときだけ閉じる いくつかから1つを選ぶ GoSurface はい 最前面のウィンドウに閉じるよう求める dismiss_on_scrim なら閉じるよう求める 自作のウィンドウ GoSheet はい シート全体を閉じる 閉じる かばん、ショップのリスト、メール GoDrawer はい Android の戻るだけ 閉じる 広い画面の横のリスト GoPopover 閉じるまで 閉じる 閉じる — そのタップは先へ届かない アイテムやスキルの詳細 GoCombobox のリスト 閉じるまで 閉じる 閉じる 検索できる選択リスト GoContextMenu · ドロップダウン · セレクト エンジンのメニューに従う エンジンのメニューに従う 閉じる 操作、短いリスト GoSnackbar いいえ — ゲームに届く 保存した · 元に戻す · 再試行 GoPromptCard いいえ — ゲームに届く 招待、取引の申し込み GoNotice 決して止めない — ゲームに届く HUD 上に固定された1行 GoBanner いいえ — ページの中にある — — 「オフラインです。再試行」 GoCoachMark 自分のカードだけ ツアーを終える ゲームに届く 初回起動のツアー GoConsole 自分のパネルだけ Escape キーで閉じる ゲームに届く デバッグコマンド それぞれがどのレイヤーで開くか、なぜその順なのかは レイヤー、戻る、入力 にある。 GoDialogs GoSurface GoSheet GoDrawer GoPopover GoContextMenu GoSnackbar GoPromptCard GoCoachMark GoConsole このページの画像はすべて同じ小さなゲームだ — 左上に体力とマナ、右上にコイン、下にスティックとクイックスロット3つ — を default_dark で表示し、その上にポップアップを1つ開いている。同じ ポップアップを14の見た目で →","",56],[5,"popup-anatomy","ポップアップの構造",0,"gohud でゲームを塞ぐポップアップのほとんど — ダイアログ、シート、ポップオーバー、コンボボックスのリスト、 自作のウィンドウ — は1つのノード、GoSurface だ。その部品を一度覚えれば、全部が分かる。 戻ると閉じるのあるヘッダー · 本文 · ステータス行 · フッター 部品 何か 触り方 レイヤー ポップアップが載る CanvasLayer。その番号で何を覆うかが決まる。 GoSurface では自分で決める。ほかは組み込み（表） 幕 背後全体にかかる覆い。カードを外れたタップを受け止める。 scrim_transparent、dismiss_on_scrim、テーマの scrim 色 カード ウィンドウそのもの — テーマのパネルの面だ。見た目によって丸い、面取り、鍛造、ゼリーになる。 card、alpha ヘッダー 任意の戻るボタン、タイトル（最大2行、あふれると「…」）、閉じるボタン。 set_title() · set_title_key() · set_back() · close_enabled · show_header ツールバー ヘッダーの下に固定された行 — 検索欄、フィルターのチップ。使うまでは隠れている。 toolbar 本文 スクロールする部分。中身はここに入れる。 body · scroll_body · clear() ステータス行 本文とフッターの間に固定された1行 — 「名前の確認に失敗」「保存中…」。 set_status_text() · set_status_key() · clear_status() フッター 下に固定されたボタン。使うまでは隠れている。 footer 固定したいものは固定の行に置く。 検索欄やエラーや保存ボタンを本文に入れると、長いリストと一緒にスクロールして 消える — プレイヤーが名前を打ち間違えても、エラーは画面の下に埋もれ、何も起きていないように見える。 toolbar、ステータス行、footer を使う。本文がスクロールしても、その場に留まる。","",-1],[5,"popup-dialogs","await で受け取るダイアログ",0,"GoDialogs は尋ねて、待つ。ノード1つに問いが3種類 — 答えが同じ行に返ってくるので、 コードがプレイヤーの体験する順に読める。 confirm() confirm(…, true) — 取り消せない操作 alert() choose() ActionLayout.HORIZONTAL","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Buy the starter pack?\", \"300 gems for a sword, a shield and 10 potions.\", \"Buy\", \"Not now\"): buy_starter_pack()",-1],[5,"the-three-questions","3種類の問い",1,"呼び出し 戻り値 用途 confirm() true か false はいかいいえ — 購入、削除、退出、上書き。 alert() なし — 待つなら await する プレイヤーが必ず見るべきこと：報酬、切れた接続。 choose() 選んだ選択肢の番号、または -1 いくつかから1つ。選択肢は String か {text, icon, danger, subtitle} だ。 confirm_key() · alert_key() 同上 翻訳キーを使う同じ呼び出し — ダイアログを開いたまま言語を変えても、文言が追従する。 ボタンの文言を空にすると、キット自身の言葉（GoConfig.text_keys の confirm、cancel）になる。 extra は本文の下に改行して足される。args はタイトルと本文の {placeholders} を 埋める：confirm(\"Buy {item}?\", \"It costs {price} gold.\", \"Buy\", \"\", \"\", {\"item\": name, \"price\": 300})。","confirm(title, body, ok_text := \"\", cancel_text := \"\", extra := \"\", args := {}, destructive := false) -> bool alert(title, body, ok_text := \"\", extra := \"\", args := {}) # 待つなら await する choose(title, options: Array, cancel_text := \"\", translate := false) -> int confirm_key(…) · alert_key(…) # 翻訳キー",59],[5,"every-way-out-has-an-answer","どう抜けても答えが返る",1,"プレイヤーが… confirm alert choose OK / 選択肢を押す true await が終わる 選んだ選択肢の番号 キャンセルを押す false — -1 ×、Escape、Android の戻るを押す false await が終わる -1 幕をタップする（dismiss_on_scrim のときだけ） false await が終わる -1 GoDialogs ノードがツリーから外れる false await が終わる -1 だから await の後のコードは必ず実行される — ダイアログの下でシーンが変わっても、答えが宙に浮いたまま残ることはない。","",59],[5,"destructive-actions","取り消せない操作",1,"元に戻せないことには destructive = true を渡す。OK ボタンが塗りつぶしの Tone.DANGER_SOLID ボタンになる — どの見た目でも赤地に白文字だ。淡く色を付けた危険ラベルでは、ライトテーマで 読めるようにするためにほぼ黒まで暗くするしかない。ウィンドウは使い回されるので、トーンは呼ぶたびに設定し直される。 キーボードフォーカスは OK にある。 どの確認も OK ボタンにフォーカスを置いて開くので、Enter や Space で確定する — 取り消せない確認でも同じだ。安全な選択が一目で分かる文言にし（「残す」）、うっかり一つでプレイヤーの進行が本当に 失われる操作は、もう一段階の手順の向こうに置く。","if await dialogs.confirm(\"Delete this save?\", \"Slot 2 — Aria, level 12. This cannot be undone.\", \"Delete\", \"Keep it\", \"\", {}, true): delete_save(2)",59],[5,"button-layout","ボタンの並べ方",1,"action_layout すること VERTICAL（既定） ボタンを全幅で縦に積む。どの言語でも安全だ — 長いドイツ語やロシア語のラベルでも窮屈にならない。 HORIZONTAL 1行に半分ずつの幅で並べる。 AUTO 両方のラベルがカードの半分の幅に1行で収まるときだけ横に並べ、収まらなければ積む。言語やサイズが変わるたびに決め直す。 action_gap はボタンどうしの間隔、body_gap はその上の間隔だ — ボタン間より広くとると、 問いと選択肢が2つの部分として読める。1つのダイアログにだけ効かせたいときは、開く前に set_next_action_layout() を呼ぶ。alert のボタン1つは常に全幅をとる。","",59],[5,"one-at-a-time","一度に1つ",1,"1つ開いている間に2つめの confirm() を呼ぶと、即座に false が返る — ダイアログがうっかり ダイアログの上に積み重なることはない。queue_when_busy を有効にすると、代わりに順番を待つ。alert() は常に待つ。 queue_limit（8）が待ち行列の長さを抑え、あふれると最も古い要求に false が返る。 pending() は待っている要求を数え、clear_pending() はそのすべてに false を返す。 choose() は並ばない：すでにダイアログが開いていれば -1 を返す。","",59],[5,"phone-and-desktop","スマホとデスクトップ",1,"choose() は Android と iOS では親指の届く下からシートとして、デスクトップでは中央のカードとして 開く。確認は幅が max_width（420dp）で抑えられ、中央に置かれる。layer_index、 max_width などの export は add_child の前に設定する。ノードがツリーに入るときに適用されるからだ。","var picked := await dialogs.choose(\"Sort the bag by\", [ {\"text\": \"Newest first\", \"icon\": GoIconSet.CLOCK}, {\"text\": \"Rarity\", \"icon\": GoIconSet.STAR}, {\"text\": \"Drop everything\", \"icon\": GoIconSet.TRASH, \"danger\": true}]) if picked >= 0: sort_bag(picked)",59],[5,"popup-surface","GoSurface — 自作のウィンドウ",0,"ポップアップが問い以上のもの — 設定、キャラクターシート、購入するアイテム — になるなら、 GoSurface の上に組む。セーフエリア、キーボード、固定の行、スクロール、戻る、フォーカス、サイズ変更はもう済んでいる。 自分では閉じない。 ×、Escape、戻る、幕のタップは close_requested を出すだけだ。ウィンドウを隠すか 解放するかは、持ち主である画面の仕事だ — 「閉じる」が保存なのか、破棄なのか、先に確認するのかは、その画面にしか分からない。","var layer := CanvasLayer.new() layer.layer = 50 add_child(layer) var window := GoSurface.new() window.set_title(\"Settings\") window.close_requested.connect(layer.queue_free) window.body.add_child(GoStyle.toggle(\"Music\", false)) window.body.add_child(GoStyle.slider(0.0, 1.0, 0.05)) var row := GoStyle.row() row.add_child(GoStyle.button(\"Cancel\", window.request_close)) row.add_child(GoStyle.button(\"Save\", save_and_close, GoStyle.Tone.PRIMARY)) window.footer.add_child(row) window.footer.visible = true layer.add_child(window)",-1],[5,"three-placements","3つの配置",1,"CENTER — 確認、設定 BOTTOM — リスト、管理画面 ANCHOR — コントロールの脇 CENTER ウィンドウの中の GoDatePicker ANCHOR には anchor_control が要る。カードは anchor_min_width が収まればその右に、 収まらなければ広いほうの側に、それも無理なら画面の内側に置かれ、上の余地のほうが大きければ上向きに開く。動くアンカーには 毎フレーム追従する。大きさは anchor_width（320）と anchor_max_height（520）で決まる。","",66],[5,"how-big-it-gets","どこまで大きくなるか",1,"寸法 規則 変える方法 余地 セーフエリアからキーボードと画面の余白（16dp、短辺の10%を超えない）を引いた範囲。 — 幅 縦向きでは余地の94%、横向きでは72%、最大480dp。 max_width · GoConfig.surface_width_ratio_* 高さ 中身の高さ（fit_content）で、余地の68%まで、上限は72%。サイズ変更できない中央のカードは、スクロールを避けるために94%まで伸びることがある。 height_ratio · max_height_ratio · max_height 密度 compact が設定されているか、画面の高さが420dp未満（横にしたスマホ）か、中身が収まらないと詰める：余白が減り、間隔が狭まり、タイトルが小さくなる。両方を測り、収まるうちでゆとりのあるほうを選ぶので、ちらつかない。 compact サイズ変更 resizable ならタイトルがハンドルになる：30%から上限までドラッグで変えられる。結果は height_changed(ratio) が知らせる。 resizable 上限を超える比率は切り詰められ、デバッグビルドで一度だけ警告が出る。キーボードはカードを押し上げ、フォーカスのある 入力欄が見えるようにスクロールする。セーフエリアのおかげで、Android と iOS でもノッチやジェスチャーバーにかからない。","",66],[5,"properties","プロパティ",1,"プロパティ 既定値 すること placement CENTER CENTER、BOTTOM、ANCHOR のいずれか dismiss_on_scrim GoConfig.dismiss_on_scrim（false） 幕をタップすると閉じるよう求める。カードの中で始まったドラッグは数えない。 scrim_transparent false ゲームを見せたままにする — それでも幕は外側のタップを受け止める。 close_enabled true × を表示し、Escape と戻るで閉じるよう求められるようにする。 show_header · scroll_body · resizable true · true · false ヘッダーの行、スクロールする本文、ドラッグのハンドル。 fit_content · compact true · false 中身に大きさを合わせる。最初から詰めて開く。 fade_in GoConfig.surface_fade_in（false） 開くときにカードをフェードインする。reduce_motion では即座に出る。 alpha -1（テーマの値） カードの面の不透明度を比率で。薄くなるのは面だけで、文字は決して薄くならない。 initial_focus なし 開いたときにフォーカスを受けるコントロール。 これらは add_child の前に設定する： scrim_transparent、show_header、resizable、 scroll_body はウィンドウがツリーに入るときに適用される。dismiss_on_scrim、close_enabled、 fade_in、initial_focus は随時読まれる。","",66],[5,"signals-and-calls","シグナルと呼び出し",1,"名前 何か close_requested ×、Escape、Android の戻る、幕のタップ — そして request_close()。出すのは最前面のウィンドウだけだ。 back_requested · set_back(action) ヘッダーの戻るボタン。ページのあるウィンドウ用。空の Callable を渡すと隠れる。 height_changed(ratio) ハンドルをドラッグした後。 is_top() · GoSurface.is_any_open() このウィンドウが戻るを受け取るウィンドウか — そもそも開いているウィンドウがあるか。 relayout() 今すぐ配置し直す。サイズに関わるプロパティを変えれば、すでに自動で行われる。","",66],[5,"popup-sheets","シートとドロワー",0,"場所の要るリストは、縦に持ったスマホでは親指のある下からせり上がり、タブレットやデスクトップでは 横から入ってくる — そこではシートがゲームを覆ってしまうからだ。 GoSheet GoDrawer · LEFT GoDrawer · RIGHT","",-1],[5,"gosheet-pages-from-the-bottom","GoSheet — 下から出るページ",1,"BOTTOM 配置でサイズ変更できる GoSurface を持つ CanvasLayer（レイヤー10）だ — だから HUD より上に出て、プレイヤーはドラッグで高くできる。 open(title) は新しいページを始める：本文、ツールバー、戻るボタンをクリアし、add_footer() で足したものを 解放する。同じシートで別のページを見せるには、もう一度呼ぶ。set_back() は最初のページへ戻るための戻るボタンを 表示する。open_key() は翻訳キーを受け取る。 close() は隠す — 解放はしないので、次の open() は即座に開く。いつ起きたかは closed と page_changed が知らせる。 height_ratio（0.6）は開くときの高さ、max_height_ratio は上限を引き上げる。dismissable （true）なら幕のタップで閉じる。 Escape と戻るはシート全体を閉じる。set_back() のあるサブページでもそうだ — 1ページ戻るのは画面上の 戻るボタンだけだ。戻るで1段ずつ戻したいなら、sheet.surface の close_requested を自分で処理する。","var sheet := GoSheet.new() add_child(sheet) func show_bag(items: Array) -> void: sheet.open(\"Bag\") var search := GoStyle.line_edit(\"Search the bag…\") search.text_changed.connect(filter_bag) sheet.toolbar().add_child(search) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, show_item.bind(item), Color.TRANSPARENT, item.description, false, GoIconSet.CHEVRON_RIGHT)) sheet.add_footer(GoStyle.button(\"Close\", sheet.close, GoStyle.Tone.PRIMARY))",71],[5,"godrawer-from-the-side","GoDrawer — 横から",1,"レイヤー80。幅は画面の42%（width_ratio）で、min_width（320dp）と max_width （420dp）の間だ — スマホでは画面の大半を覆うので、そこではシートのほうがよい。 パネルは画面の端まで届き、中身だけがセーフエリアの内側に入る。だから丸めた角が最初の行を切り落とさない。 LEFT はアラビア語でも画面の左だ。「始まりの側」であることが要点なら follow_text_direction を 有効にする。実際にどちらに出たかは effective_side() が教えてくれる。 open(title) は本文をそのまま残す — 一度だけ埋める。set_title(\"\") はヘッダーを隠す。 motion_seconds（0.2）で滑り込み、reduce_motion なら即座に出る。 Android の戻るはドロワーを閉じるが、Escape は閉じない。 ドロワーが聞くのはシステムの戻るだけだ。デスクトップでは 自分のキー割り当てから drawer.close() を呼ぶ — また、GoSurface.is_any_open() はドロワーを数えない ことに注意する。drawer.is_open() に尋ねる。","var drawer := GoDrawer.new() drawer.side = GoDrawer.Side.LEFT drawer.follow_text_direction = true # 始まりの側：左、アラビア語では右 add_child(drawer) drawer.body.add_child(GoNavBar.drawer_list([{\"icon\": GoIconSet.HOME, \"text\": \"Town\"}, {\"icon\": GoIconSet.MAP, \"text\": \"World map\"}], 0, go_to)) drawer.open(\"Menu\")",71],[5,"popup-anchored","コントロールの脇に出るカードとメニュー",0,"プレイヤーが今押したものには、画面の真ん中ではなく指のすぐ横で答えるべきだ。 GoPopover GoContextMenu GoStyle.dropdown() GoStyle.select() GoCombobox","",-1],[5,"gopopover-a-card-on-the-thing-pressed","GoPopover — 押したものに付くカード",1,"レイヤー、アンカー、後片付けまで配線済みの ANCHOR サーフェスだ — どのゲームも何度も書く、あの10行である。 一度に1つ：2つめを開くと1つめが閉じる。カードが積み重なると画面が埋まり、どのカードがどのスロットのものか 誰にも分からなくなるからだ。幕は透明だ — 装備を見比べるために開いたカードが、その装備を暗くしてはならない — が、外側の最初のタップは受け止める。そのタップはカードを閉じるだけで、先へは届かない。 オプション 既定値 すること title \"\" × 付きのヘッダー。空ならヘッダーなし。 width · max_height 320 · 520 カードの大きさ。 dismissable true 外側のタップで閉じる。 compact · alpha · translate false · -1 · false 詰めた間隔、面の不透明度、タイトルを翻訳キーとして扱う。 layer 95 開く先の CanvasLayer。 GoPopover.close() と GoPopover.is_open() は static だ。open() はサーフェスを返す — アンカーがツリーにないときは null なので、await shown.close_requested の前に確かめる。 ホバーのツールチップではない。 タッチにホバーはない。マウスでしか現れないものは、プレイヤーの半分には見えない。 そして dismissable = false でタイトルもなければ、画面上にそれを閉じるものは何もない — Escape、戻る、自分で呼ぶ処理だけだ。","slot.pressed.connect(func() -> void: var card := GoStyle.item_card({\"icon\": GoIconSet.POTION, \"title\": \"Health potion\", \"subtitle\": \"Heals 50 HP · 12 left\"}, false) GoPopover.open(slot, card, {\"width\": 280}))",74],[5,"gocontextmenu-long-press-and-right-click","GoContextMenu — 長押しと右クリック",1,"右クリックはすぐに開く。指を0.5秒（HOLD_SECONDS）置くと開き、12dp を超えて動くと 取り消す — だからリストをスクロールしてもメニューは出てこない。 項目は {text, action, icon, disabled, checked, separator, danger, translate} だ。押したものによって項目が変わるなら、 配列の代わりに Callable を渡す。メニューが開くたびに呼ばれる。 danger は文言の前に「⚠ 」を付ける — エンジンのメニューは全項目の色をまとめてしか変えられないからだ。 エンジンの PopupMenu を GoStyle.style_popup() で装ったものだ。開いているサーフェスとしては数えない。 長押しには、もう1つの入り口が要る。 隠れたジェスチャーは誰にも見つけられない。目に見える ⋯ ボタン （上のように open_at()）と組み合わせるか、コーチマークで一度教える。","var menu := [ {\"text\": \"Use\", \"icon\": GoIconSet.POTION, \"action\": use}, {\"separator\": true}, {\"text\": \"Drop\", \"icon\": GoIconSet.TRASH, \"action\": drop, \"danger\": true}] GoContextMenu.attach(slot, menu) var more := GoStyle.icon_button(GoIconSet.MORE, Callable(), -1, &\"more\") more.pressed.connect(func() -> void: GoContextMenu.open_at(more, menu))",74],[5,"dropdowns-selects-and-the-split-button","ドロップダウン、セレクト、スプリットボタン",1,"3つともエンジンのポップアップメニューを開く：dropdown() は操作を実行する MenuButton、 select() は値を保つ OptionButton、GoSplitButton はメインの操作に矢印側のメニューを 足したもの（chosen(index)）だ。メニューはあえて完全に不透明にしてある — 独立した OS ウィンドウに出るメニューは、 半透明のピクセルを黒くしてしまう。","var sort := GoStyle.dropdown(\"Sort\", [\"Highest score\", \"Most wins\", {\"text\": \"Friends only\", \"disabled\": true}], func(index: int) -> void: sort_board(index)) var quality := GoStyle.select([\"Low\", \"Medium\", \"High\", \"Ultra\"], \"Quality\") quality.item_selected.connect(func(index: int) -> void: settings.quality = index) var send := GoSplitButton.make(\"Send\", send_now, [\"Send later\", \"Save as draft\"])",74],[5,"gocombobox-a-list-that-searches","GoCombobox — 検索できるリスト",1,"押すと、レイヤー96に透明な幕とともに脇に留まるリストを開く。項目が search_threshold（8）個以上あると 検索欄が現れてフォーカスを取る。大文字と小文字を区別せず、文言やヒントのどこにでも一致し、結果がなければそう 表示する。リストの幅は list_width（0 = ボタンの幅、最小180dp）で決める。","var friend := GoCombobox.make(friend_names, -1, \"Find a friend\") friend.picked.connect(func(index: int) -> void: invite(friend_names[index]))",74],[5,"popup-nonblocking","ゲームを決して止めないポップアップ",0,"プレイしながら読める知らせだ。どれにも幕はない。カードそのもの以外へのタップは ゲームに届く。 GoSnackbar GoNotice GoPromptCard GoStyle.tooltip_node()","",-1],[5,"gosnackbar-a-message-with-an-undo","GoSnackbar — 「元に戻す」付きのメッセージ",1,"post() のキー すること text · title · args · translate メッセージ、任意の太字の行、{placeholders}、翻訳キー。 tone · icon アクセントの色（GoTheme.SUCCESS、WARNING…）とアイコン。 actions · closable ボタン — String か {text, action} — と ×。 seconds 表示する時間。負の値ならテーマの notice_duration_ms。0 なら閉じられるまで — そのときはボタンを付ける。 post() は押されたボタンの番号を返し、時間切れや閉じられたときは -1 を返す。投稿は 順番待ちし（queue_limit 4、あふれると最も古いものが -1 で外れる）、表示中に同じ文言をもう一度投稿するとタイマーを 延ばすだけになる。下端（または上端、placement）のセーフエリアとキーボードの上、レイヤー90に出る — ドロワーの上でも 読める。tap_to_dismiss（有効）なら、ボタンのないカードはタップで閉じる。カードの外側のタップは常に ゲームに届く。show_text() と show_key() は1行で書ける形だ。 スナックバーで決して問いかけない。 スナックバーはひとりでに消える。大事な選択はダイアログの役目だ。","var snack := GoSnackbar.new() add_child(snack) if await snack.post({\"text\": \"Dropped {name}\", \"args\": {\"name\": item.name}, \"icon\": GoIconSet.TRASH, \"actions\": [\"Undo\"], \"seconds\": 5.0}) == 0: restore(item)",79],[5,"gonotice-a-line-on-the-hud","GoNotice — HUD 上の1行",1,"自分で置く素のパネルだ — GoHudAnchor の中、隅、どこでも。入力もフォーカスも取らないので、 その上を押せば下のボタンに届き、新しいメッセージは古いものを置き換える。幅を与える： preferred_width(limit) は短い文には自然な幅を返し、長い文は limit の中で折り返す。 set_content() は文字の代わりに任意のコントロールを表示する。","var notice := GoNotice.new() hud_corner.add_child(notice) notice.show_text(\"Game saved\", GoTheme.SUCCESS) notice.custom_minimum_size.x = notice.preferred_width(340)",79],[5,"gopromptcard-a-question-that-can-wait","GoPromptCard — 待ってくれる問いかけ",1,"隠れた状態で始まる — show() を呼ぶ。自前のタイマーはないので、問いに期限があるなら自分で付ける。 ボタンを押しても閉じない — どうするかは操作が決める。×（set_closable(true)）は closed を出す。 fit_width(width) は幅を設定し、フォントから高さを予測する。だから、それに合わせて配置したものが1フレーム後に跳ねない。 面は hud_alpha に従う — ウィンドウではなく HUD の一部だ。","var spot := GoHudAnchor.new() spot.spot = GoHudAnchor.Spot.TOP_CENTER spot.reserve_space = false spot.avoid_peers = true # 体力バーを覆わず、その下へよける hud.add_child(spot) var invite := GoPromptCard.new() spot.add_child(invite) invite.set_icon(GoIconSet.USERS, Color.TRANSPARENT, true) invite.set_title(\"Party invite from Ann\") invite.set_subtitle(\"Dragon's Lair · 3 / 4 members\") invite.set_actions([{\"text\": \"Accept\", \"action\": accept, \"primary\": true}, {\"text\": \"Decline\", \"action\": invite.hide}]) invite.fit_width(340) invite.show() get_tree().create_timer(15.0).timeout.connect(invite.hide)",79],[5,"gobanner-and-tooltips","GoBanner とツールチップ",1,"GoBanner.make(\"You're offline.\", [{\"text\": \"Retry\", \"action\": reconnect}], GoIconSet.WARNING) はページそのものの中、 コンテンツの上に置かれ、時間切れにならない。ボタンを押すと閉じるが、\"keep\": true があれば残る。 GoStyle.tooltip_node(text) は _make_custom_tooltip() から返すものだ — 下地（TooltipPanel）は エンジンが、文字は gohud が描き、260dp を超えると折り返す。ツールチップはマウス用だ。プレイヤーに必要なものを決してその陰に隠さない。","",79],[5,"popup-guides","ツアーとコンソール",0,"GoCoachMark GoConsole","",-1],[5,"gocoachmark-a-tour-of-the-real-controls","GoCoachMark — 実物のコントロールを巡るツアー",1,"実物のコントロールを囲むリングと、その脇のカードだ。対象を押すと進む（その pressed シグナル、またはステップの \"signal\"）。「次へ」と「スキップ」はカードにある。隠れた対象は飛ばされる。 カードは画面の中央（avoid_center_band）、HUD のアンカー、keep_clear を避けて置かれる。 GoSurface が1つでも開いている間、ツアーは隠れて待つ。戻るか Escape は finished(false) でツアーを終える。 自前のレイヤーを持たない — 最後に追加するか、HUD より上のレイヤーに追加する。","var tour := GoCoachMark.new() tour.keep_clear = [top_bar] tour_layer.add_child(tour) tour.finished.connect(func(completed: bool) -> void: save.tutorial_done = true) tour.start([{\"target\": bag_button, \"title\": \"Bag\", \"body\": \"Everything you pick up lands here.\"}, {\"target\": map_button, \"title\": \"Map\", \"body\": \"Tap to open the full map.\"}])",84],[5,"goconsole-cheats-while-you-build","GoConsole — 開発中のチート",1,"レイヤー200 — すべての上なので、ダイアログの上からでもデバッグできる — で、ツリーが一時停止していても動き続ける。 打つそばからコマンドを提案するパレットが出て、上下キーで履歴をたどり、Escape で閉じる。組み込みのキーはない：自分で割り当てる。 debug_only（有効）はリリースビルドでコンソールを止める — open() も run() も。チートコマンドが プレイヤーの手に渡れば、ゲームの経済は初日で終わる。","var console := GoConsole.new() add_child(console) console.register(\"give\", \"give <item> <count>\", func(args: PackedStringArray) -> String: return \"gave %s x%s\" % [args[0], args[1]] if args.size() >= 2 else \"give <item> <count>\") func _unhandled_input(event: InputEvent) -> void: if event.is_action_pressed(&\"dev_console\"): console.toggle()",84],[5,"popup-stack","レイヤー、戻る、入力",0,"何かが開いている間にプレイヤーが何に触れられるかは、3つの規則で決まる：何が上にあるか、 戻るは誰のものか、タップは誰が受けるか。","",-1],[5,"what-sits-on-top","何が上にあるか",1,"レイヤー そこにあるもの 設定方法 5 自分の HUD（自分で決める） — 10 GoSheet CanvasLayer.layer ~50 自作の GoSurface ウィンドウ、ポーズメニュー 自分の CanvasLayer 80 GoDrawer CanvasLayer.layer 90 GoSnackbar layer_index 95 GoPopover \"layer\" オプション 96 GoCombobox のリスト — 100 GoDialogs layer_index 200 GoConsole layer_index この順には理由がある：スナックバーは今起きたことを知らせるので、ドロワーの上で読める。ポップオーバーは今押したものに 属するので、その上に乗る。ダイアログは問いを投げるので両方を覆う。コンソールはすべてを覆う — ほかが全部おかしくなった ときに開くものだからだ。","",87],[5,"who-owns-back","戻るは誰のものか",1,"答えるのは最前面のウィンドウだけだ。 開いているサーフェスのうち、いちばん高いレイヤーのもの（同じならツリーで最も後のもの）が、 Escape、ゲームパッドのキャンセル（ui_cancel）、Android の戻る、幕のタップを受け取る。重ねたウィンドウは1枚ずつ閉じ、 まとめては閉じない。 Android の戻るは1フレーム遅れて処理されるので、1回押してウィンドウが2枚閉じることはない。 戻るを持つものが開いている間、Android の戻るはアプリを終了しない（GoBackPolicy が持ち主を数え、 最後の1つが閉じると quit_on_go_back を元に戻す）。戻るを受け取る自作のポップアップは GoBackPolicy.acquire() と release() を呼ぶ — _exit_tree でも。 ドロワー、コーチマークのツアー、フォームは、サーフェスが開いている間は身を引く — 戻るはまずサーフェスに届く。 GoConfig.close_on_back（有効）がサーフェスのスイッチだ。","",87],[5,"who-takes-a-tap","タップは誰が受けるか",1,"サーフェスは画面全体を覆って入力を止める — 透明な幕でもそうだ。開いている間、下のレイヤーにあるものは 何も押せない。上のレイヤー（スナックバー）は押せる。 マウスホイールやピンチのジェスチャーもウィンドウで止まる：リストの端を越えてスクロールしても、ゲームはスクロールしない。 コントロールを通らないゲームの入力 — 移動用の _unhandled_input、カメラのドラッグ — は止めるべきだ： if GoSurface.is_any_open(): return。これでダイアログ、シート、ポップオーバー、コンボボックスが含まれる。ドロワーには 別に is_open() を尋ねる。 スナックバー、通知、プロンプトカード、コーチマークは自分のカードでだけ入力を受ける。それ以外の場所では、ゲームが受け取る。","",87],[5,"focus","フォーカス",1,"ポインターで開いたウィンドウは何にもフォーカスを与えない — タッチでフォーカスリングが光ることはない。キーボードやゲームパッドで 開くと、閉じるボタン（または initial_focus）がフォーカスを受ける。開いている間フォーカスはウィンドウの中に留まり、 閉じると、それまでフォーカスを持っていたコントロールへ戻る。ダイアログは毎回 OK にフォーカスを置く。","",87],[5,"pausing-the-game","ゲームの一時停止",1,"ツリーを一時停止するとポップアップも止まる — 動き続けるのはコンソールだけだ。ポーズメニューなら、そのレイヤーに process_mode = PROCESS_MODE_ALWAYS を与える。すると、ゲームが止まっている間もウィンドウ、ボタン、戻るが動き続ける。","",87],[5,"popup-looks","すべての見た目で同じポップアップ",0,"このページ冒頭の確認を同じゲームの上に出し、プリセットだけを変えた。コードは同一だ — 残りはテーマ、スキン、アイコンが受け持つ。 default_dark default_light scifi_dark scifi_light medieval_dark medieval_light material_light 新登場 material_dark 新登場 kids_light 新登場 kids_dark 新登場 comic_light 新登場 comic_dark 新登場 arcade_light 新登場 arcade_dark 新登場","",-1],[5,"what-each-look-changes","見た目ごとに変わるもの",1,"見た目 ウィンドウ ヘッダーとボタン デフォルト 丸い角（18dp）、柔らかな影、ゲームの上で80%の不透明度 素直なタイトルと ×。主ボタンは浮き上がり、押すと沈む SF ネオンの縁と発光を持つ面取りの角。縁はアクセント色に染まる ブラケット型のフォーカス印 中世 鍛造の枠 — 鉄と革、あるいは羊皮紙 — にリベットと角飾り Cinzel のタイトル Material 3 28dp の角、24dp の内側余白、完全に不透明 Roboto の 24sp 見出し。48dp のターゲットに 40dp の下地を収めたピル型ボタン キッズ 柔らかな影の付いたゼリーキャンディのカード、完全に不透明 お日さま色のタイトルリボン（夜はミント）、丸いキャンディの閉じるボタン、押すとぷにっとつぶれるボタン コミック 太いインクの輪郭とくっきりした影、完全に不透明 黄色のタイトルキャプション、インクで描いた丸い閉じるボタン、押すと影が消えるボタン アーケード 厚いボード — 淡い内側を色の枠が囲む — 完全に不透明 インクで縁取った白いタイトルを載せた金色のタイトルバナー、丸い赤の閉じるキー、押すと跳ねる塗られたキー","",93],[5,"dress-a-popup-from-a-skin","スキンでポップアップを装う",1,"スキンは、Theme が届かない部分を決める。ポップアップが呼ぶのは次のフックだ — 自分の GoSkin サブクラスで上書きする。既定では何もしない。 フック 装うもの title_plate_box() · title_plate_ink() · title_plate_min_size() ウィンドウのタイトルの背後に敷く下地。タイトルはその中央に乗り、1行に収まるよう最小サイズ（15）まで縮む。 dress_close_button(button) ウィンドウの × — キッズでは丸いキャンディに、コミックではインクで描いた円盤に、アーケードでは丸い赤のキーになる。 dress_title(label) ウィンドウのタイトルのラベル — アーケードでは白いタイトルをインクで縁取る。 press_feedback(control) gohud が作ったボタンに指が触れた瞬間に走る — キッズではぷにっとつぶれ、アーケードではぽんと跳ねる。 floating_box() · notice_box() · drawer_box() · banner_box() · overlay_box() プロンプトカードとコーチマークのカード、スナックバーと通知、ドロワー、バナー、コンソールの面。 coach_ring_box() · draw_coach_pointer() ツアーのリングとポインター。","",93],[5,"how-see-through","どこまで透けるか",1,"ポップアップは種類ごとに自分の不透明度に従うので、HUD のカードは軽く、ダイアログはしっかりと保てる：ウィンドウ、シート、 ダイアログ、ポップオーバー、コンボボックスは panel_alpha、ドロワーとコーチマークのカードは card_alpha、 プロンプトカードとコンソールは hud_alpha、スナックバーと通知は notice_alpha、メニューは popup_alpha に従う。 Material とキッズはすべてを不透明にする。コミックも同じだが、プロンプトカードとコンソールだけは 92% だ。アーケードも同じで、その2つだけが 94% になる。1種類だけ変えるなら GoConfig.container_alpha_overrides、全部なら container_alpha（比率 — 0.95）、ウィンドウ1つならその alpha で上書きする。薄くなるのは面だけで、 文字が透けることは決してない。不透明度の詳細 →","",93],[5,"popup-config","すべてのポップアップを形づくる設定",0,"GoConfig（GoUi.config）のフィールドだ。いくつかはウィンドウが作られるときにコピーされるので、 UI を作る前に設定する — あるいは変更後に GoUi.refresh() を呼ぶ。 フィールド 既定値 すること surface_max_width · surface_max_height 480 · 700 ウィンドウの最大の大きさ。 surface_height_ratio · surface_max_height_ratio 0.68 · 0.72 ふだんの高さと上限（ドラッグの限界でもある）。 surface_fit_max_height_ratio 0.94 中身に合わせる中央のカードが、スクロールし始めるまでに伸びられる限度。 surface_width_ratio_portrait · …_landscape 0.94 · 0.72 余地に対する幅の割合。 dismiss_on_scrim false 幕のタップでウィンドウとダイアログが閉じる。ウィンドウ作成時にコピーされる。 surface_fade_in · fade_seconds false · 0.14 ウィンドウをフェードインするかどうかと、その速さ。 close_on_back true Escape、ui_cancel、Android の戻るが最前面のウィンドウを閉じる。 close_button_visual 36 × の見た目の大きさ — タッチターゲットは 48dp のまま。 suppress_pointer_focus_ring true タッチやマウスで開いたウィンドウにはフォーカスリングを出さない。 container_alpha · container_alpha_overrides -1 · {} すべての面の不透明度、または種類ごとの不透明度（GoTheme.BOX_*）。 reduce_motion false フェード、スライド、脈動、ぷにっとつぶれる動きをすべて止める。 min_touch_size 48 プロンプトカードとコーチマークのボタンの高さ。 respect_safe_area true ウィンドウをノッチとジェスチャーバーから離す。 text_keys · text_overrides — キット自身の言葉：閉じる、戻る、確認、キャンセル、次へ、完了、スキップ、検索、空… sound_cues · ハプティクス — 開いた、閉じた、確定した、キャンセルした、タップしたときに GoFeedback が鳴らす音と振動。","",-1],[5,"popup-recipes","レシピ",0,"コピーして貼り付け、文言を変える。ここにある呼び出しは、すべてソースと照らし合わせて確かめてある。","",-1],[5,"a-purchase-with-the-price-in-it","価格入りの購入確認",1,"","func buy(item_name: String, price: int) -> void: if await dialogs.confirm(\"Buy {item}?\", \"It costs {price} gold.\", \"Buy\", \"\", \"\", {\"item\": item_name, \"price\": price}): purchase(item_name)",98],[5,"a-settings-window-with-a-pinned-save","保存ボタンを固定した設定ウィンドウ",1,"","func open_settings() -> void: var layer := CanvasLayer.new() layer.layer = 50 add_child(layer) var window := GoSurface.new() window.set_title(\"Settings\") window.dismiss_on_scrim = true window.close_requested.connect(layer.queue_free) window.body.add_child(GoStyle.section(\"Sound\", false)) window.body.add_child(GoStyle.toggle(\"Music\", false)) window.body.add_child(GoStyle.slider(0.0, 1.0, 0.05)) var row := GoStyle.row() row.add_child(GoStyle.button(\"Cancel\", window.request_close)) row.add_child(GoStyle.button(\"Save\", func() -> void: save_settings() layer.queue_free(), GoStyle.Tone.PRIMARY)) window.footer.add_child(row) window.footer.visible = true layer.add_child(window)",98],[5,"a-form-that-says-what-is-wrong","何が間違っているかを伝えるフォーム",1,"","var field := GoField.make(\"Name\", GoStyle.line_edit(), \"3–12 letters\") window.body.add_child(field) create_button.pressed.connect(func() -> void: if name_is_taken(): field.set_error(\"That name is taken\") window.set_status_text(\"Name check failed\", GoTheme.DANGER) else: window.clear_status() create_character())",98],[5,"a-date-in-a-sheet","シートで日付を選ぶ",1,"","sheet.open(\"Delivery date\") var picker := GoDatePicker.make({\"year\": 2026, \"month\": 10, \"day\": 14}, func(date: Dictionary) -> void: delivery = date sheet.close()) picker.min_date = GoDatePicker.today() sheet.body.add_child(picker)",98],[5,"a-pause-menu","ポーズメニュー",1,"","func pause() -> void: get_tree().paused = true var layer := CanvasLayer.new() layer.layer = 50 layer.process_mode = Node.PROCESS_MODE_ALWAYS # ゲームが一時停止しても動き続ける add_child(layer) var menu := GoSurface.new() menu.set_title(\"Paused\") menu.close_requested.connect(func() -> void: get_tree().paused = false layer.queue_free()) menu.body.add_child(GoStyle.button(\"Resume\", menu.request_close, GoStyle.Tone.PRIMARY)) menu.body.add_child(GoStyle.button(\"Settings\", open_settings)) menu.body.add_child(GoStyle.button(\"Quit to title\", quit_to_title, GoStyle.Tone.DANGER)) layer.add_child(menu)",98],[5,"gameplay-that-waits-for-popups","ポップアップを待つゲームプレイ",1,"","func _unhandled_input(event: InputEvent) -> void: if GoSurface.is_any_open() or drawer.is_open(): return handle_gameplay(event)",98],[5,"popup-pitfalls","落とし穴",0,"GoSurface は自分では解放されない。 close_requested をつながないと、× を押しても何も起きない。 add_child の後に設定したオプション — scrim_transparent、show_header、resizable、 scroll_body、そして GoDialogs の layer_index と max_width — は適用されない。 2つめの confirm() は即座に false を返す。 2つの問いが重なりうるなら queue_when_busy を有効にする。 Enter で確定する。 取り消せないダイアログでも OK にフォーカスがある。 シートで戻るを押すと、シートが閉じる。 サブページが閉じるのではない。 Escape はドロワーを閉じず、 is_any_open() もドロワーを見ない。 ポップオーバーやコンボボックスのリストは、閉じるまでゲームを塞ぐ。 幕が透明でもそうだ — しかも dismissable = false でタイトルのないポップオーバーには、画面上に閉じる手段がない。 プロンプトカードは隠れた状態で始まり、 時間切れもない。 seconds: 0 でボタンのないスナックバーは、いつまでも消えない。 しかも既定では自分のカードへのタップを受け取る。 誰も知らない長押しは、誰も使わない機能だ。 ⋯ も表示する。 一時停止したツリーはポップアップも止める。 そのレイヤーに PROCESS_MODE_ALWAYS を使う。 幅のない通知は いちばん狭く縮む — preferred_width() を使う。 スナックバーで尋ねず、ダイアログで知らせない。 無視された問いは消えてしまうし、知らせのためにゲームを止めるべきではない。","",-1],[6,"gosurface-the-shell","GoSurface — 外殻",1,"CENTER BOTTOM ANCHOR ポップアップもシートもドロップダウンも、すべてこれ1つを使う。セーフエリア、仮想キーボード、 固定ヘッダーとフッター、スクロールする本文、どのウィンドウが最前面か、フォーカスの復帰、 戻るボタンの所有権、ドラッグでのサイズ変更まで面倒をみる。 配置 見え方 用途 CENTER 中央のカード 確認、設定 BOTTOM 下からせり上がるシート リスト、管理画面 ANCHOR コントロールの脇に留まるカード ドロップダウン、コンテキストメニュー 自分では消えない。 close_requested を受けて隠すか解放するかは、持ち主である画面の仕事だ。 外殻にはなぜ閉じようとしているのか（保存して閉じるのか、破棄するのか）が分からないからである。","",-1],[6,"gosheet-a-page-from-the-bottom","GoSheet — 下から出るページ",1,"GoSheet 自前の CanvasLayer を持つので、HUD より確実に上に出る。open() は本文を空にし、 戻るボタンと固定行をいったん無効にする — 戻る先のない画面で死んだボタンが見えていると、 壊れているように読めるからだ。","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"インベントリ\") sheet.toolbar().add_child(GoStyle.line_edit(\"検索…\")) sheet.toolbar().visible = true sheet.footer().add_child(GoStyle.button(\"閉じる\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",-1],[6,"godialogs-confirmations-you-await","GoDialogs — await で受け取る確認",1,"confirm() destructive choose() confirm(title, body, ok_text, cancel_text, extra, args, destructive) — 本文より後ろはすべて省略でき、 alert() はボタン1つで同じように使える。取り消せない操作には destructive を立てる。 確認ボタンが塗りつぶしの GoStyle.Tone.DANGER_SOLID になる。ライトテーマでは、淡く色を付けた危険ラベルは 黒い文字に見えるまで暗くするしかないが、塗りつぶしのボタンなら赤地に白文字を保てる。ウィンドウは1つを使い回すので トーンは呼び出しのたびに付け直され、1つ開いている間に2つめの confirm() を呼ぶと即座に false が返る。confirm_key() は翻訳キーを受け取る。 ボタンの並べ方。 action_layout の既定は VERTICAL（長い訳文でも安全だ）、 HORIZONTAL なら半分ずつの幅で1行に、AUTO なら両方のラベルがカードの半分に1行で 収まるときだけ横に並べ、収まらなければ縦に積む。action_gap はボタンどうしの間隔、 body_gap はその上の間隔だ — ボタン間より広くとると、問いと選択肢が2つの塊として読める。 1つのダイアログにだけ効かせたいときは、開く前に set_next_action_layout() を呼ぶ。 ボタンの行は最初にダイアログを開いたときに組み立てられるので、オートロードした GoDialogs でも 起動時のコストはない。","if await dialogs.confirm(\"セーブデータの削除\", \"元に戻せません。\"): delete_save()",-1],[6,"goform-a-width-capped-form","GoForm — 幅に上限のあるフォーム",1,"GoForm 配下のラベルが必ず折り返すことを保証する。 これがないと、長い一文が1行に伸びて最小幅が画面を超え、 左右が切れる — 自分がどの画面にいるのかすら分からなくなる。シーンごとに手で折り返しを有効にする方法は、 毎回必ず忘れられる。","",-1],[6,"goscroll-touch-scrolling","GoScroll — タッチでのスクロール",1,"GoScroll · GoScroll.horizontal() 中に入れるのは1つだけにする。見出しやボタンの行は外側だ — 長いリストがそれらを画面外へ 押し出してはならない。use_panel_edge() は、中身のインデントを保ったまま スクロールバーをカードの既存の余白へ移す。","",-1],[7,"gonotice-snackbar","GoNotice — スナックバー",1,"GoNotice GoSnackbar 入力を横取りしない。 通知は読むものであって、押すものではない。フォーカスを取らず、ゲームの入力も 塞がず、その下のボタンはそのまま押せる。確認が要るなら GoDialogs、選択が要るなら GoPromptCard を使う。","",-1],[7,"gopromptcard-a-question-that-does-not-block","GoPromptCard — 画面を塞がない問いかけ",1,"GoPromptCard 幕を張らずに片側へ浮かぶ。ゲームは動き続ける。","",-1],[7,"gocoachmark-guided-tour","GoCoachMark — ガイドツアー",1,"GoCoachMark 実物のコントロールを1つずつ指し示す。入力を受けるのはカードだけなので、強調されたコントロールを 押すこと自体がツアーを進める — 「ここを押してください」が文章ではなく操作になる。 title と body には翻訳キーでも、そのままの文字列でも渡せる。 対象が消えてしまったステップは飛ばされる。","tour.start([ {\"target\": bag_button, \"title\": \"かばん\", \"body\": \"拾ったものはすべてここに入る。\"}, {\"target\": map_button, \"title\": \"マップ\", \"body\": \"押すと全体マップが開く。\"}, ])",-1],[8,"the-small-things-decide-whether-it-looks-good","出来を決めるのは小さなところだ",1,"大きなパネルをいくら磨いても、目に留まるのはいつも小さなものだ — 途中で切れた単語、欠けた発光、 窮屈なスロット。2026-09-13 にそうした4つが指摘され、デモ画面ではなくウィジェットとテーマの側で直した。 だから、どの画面でも同じ結果になる。 何が起きたか 原因 直し方 コーチマークの Done が Don/e になった 折り返しを有効にしたボタンは文字幅を最小幅から差し引く — 狭められると単語の途中で割れる GoStyle.fit_words(): 1単語なら決して折り返さず、複数語なら折り返すがいちばん長い単語は必ず収まる。判定は翻訳キーではなく実際に表示される文字で行い、言語が変わればフォームが付け直す 全幅ボタンの発光が、左側だけ縦に切れた スクロールコンテナは例外なく自分の端で切り取る。右だけはレールの余白のおかげで残っていた GoScroll が親の余白を借りて端を 12dp 外へ押し出し、内側で返す — 中身の位置は動かない スロットの中で、時間・アイコン・個数が縦に積み上がった 48dp の中に3行あった アイコンは中央に大きく、ショートカットは左上、個数は右下のバッジ、残り時間はアイコンに重ねたバッジへ — バッジのパネルはスキンの badge_box() から来る ドロップダウンが平坦で、どれを選んでいるか見えない 項目のホバーにボタンのパネルを使い、ラジオの印はエンジンの薄い既定のままだった 専用のホバーパネル（淡いアクセント）、チェックボックスと同じラジオの絵、タッチに合わせた項目の高さ ドロップダウン — ホバーパネルとラジオ印 スロット — 隅のバッジと残り時間（SF） アイコンだけのボタンには GoStyle.icon_button(icon, action, -1, tooltip_key) で説明を与える — マウス利用者へのツールチップも、スクリーンリーダー向けのアクセシビリティ名も、この1つの値から取る。 ツールチップは gohud が自分で描く。エンジンの既定は、幅の計算が狂うと文字を1文字ずつ改行してしまう （幅 1dp と実測された）。 コーチマークのカードは固定物を避ける 横持ちでは、カードが画面のいちばん上か下の端へ送られていた — ヘッダーや HUD がちょうど居座る場所だ。 デモではヘッダーの → × の上に重なっていた。いまは対象と同じ高さにとどまり、場所を確保している GoHudAnchor を回り込み、そのほか避けたいものは keep_clear で受け取る。 対象を覆わずに障害物から外れる最短の距離だけ動き、画面が狭くてすべてを避けきれないときはその場にとどまる — 重なるほうが、消えるよりましだ。ページより上にあると読めるだけの立体感は、スキンのダイヤルから来る (float_shadow_size、float_shadow_lift、float_shadow_alpha。面取り系のスキンは float_glow_size)。","tour.keep_clear = [header_bar, toolbar] # アンカーではない固定物",-1],[8,"screens-with-a-mouse-and-a-keyboard","マウスとキーボードのある画面",1,"指にはホバー状態がない。 モバイルだけを見て作ると、デスクトップにしかない2つの状態が未確認のまま残る — そして実際、片方は壊れていた。gohud のフォーカスリングが主ボタンの上で見えなかったのだ。パネルが アクセント色で、リングも同じ色。1.00:1、同じ色を同じ色の上に描いていた。キーボードで移動すると、 自分がどこにいるのか分からなかった。 上から 通常 · ホバー · フォーカス。塗りつぶしのボタンには、自分のパネルと対比するリングが付く。 塗りつぶしのボタン（GoPrimaryButton、GoDangerSolidButton）は 自分のパネルと対比するリングを使う — ダークテーマでは暗く、ライトテーマでは白く、SF では暗い照準 ブラケットになる。コントラスト検査はフォーカスリングを、それが載っているパネルに対して測るので、 パレットを変えてもこの規則は生き残る（WCAG 2.4.11 はフォーカス表示に 3:1 を求めている）。","",-1],[8,"hud-widgets","HUD ウィジェット",0,"","",-1],[8,"gohudanchor-nine-spots","GoHudAnchor — 9か所",1,"TOP_LEFT · TOP_RIGHT · BOTTOM_LEFT · BOTTOM_RIGHT セーフエリアと画面端の余白を尊重する。landscape_spot を与えれば横持ちで移動する — 縦持ちで下中央にあるコントロールを、横持ちでは右下へ回せる。 なぜ必要か。 HUD ごとに手で書いたアンカーとオフセットは必ずずれていく。ノッチのある端末では体力バーが カメラの切り欠きの下に入り、横持ちでは操作ボタンがジェスチャーバーの上に載る。その算術を1か所に集めてある。 本文を HUD の下に潜り込ませない スクロールする画面が HUD と同じ表示面を分け合うと、本文はその下へ滑り込み、2組の文字が重なって どちらも読めなくなる。このアドオンでも2度起きた。入力欄のプレースホルダーがクイックスロットの間から はみ出し、設定のトグルのつまみが体力バーの上に載った。 それぞれの矩形は失う面積がいちばん小さい方向へ避ける。右上のバーは、縦持ちのスマートフォンでは下へ 回り込み（高さの 13%）、横持ちでは横へ回り込む（幅の 21%） — 横持ちで縦に避ければ画面の 27% を失う。 すでに明け渡した領域は、次の矩形を測る前に差し引かれる。 HUD どうしもぶつかる 9か所は画面を分割するだけで、部品どうしがぶつからないことまでは保証しない。上中央の幅広い スナックバーが、右上の体力バーの真上に着地して値を隠した — 残り体力が読めなかったのだ。 よけるのは縦方向だけだ — 横にも動かすと、中央揃えのトーストが出るたびに違う場所に現れてしまう。 しかも、避けるのは自分からはよけない部品に対してだけだ。両方が譲ると、2つは永遠に場所を入れ替え続ける。","form.avoid_hud = true # 表示中の GoHudAnchor をすべて避ける joystick_anchor.reserve_space = false # …指が触れたときだけ現れるものは除く notice_anchor.avoid_peers = true # 固定 HUD の下へ落ち着く notice_anchor.reserve_space = false # 出ている間にページを押しのけたりはしない",116],[8,"gobar-health-mana-experience","GoBar — 体力・マナ・経験値",1,"GoBar 変化は 0.18 秒かけてなめらかに動く — 跳ねる体力バーは、どれだけ強く殴られたのかを伝えない。 reduce_motion にすれば即座に反映する。大きな数は 12.3k のように略記するので、 桁が増減してもバーの幅が揺れない。","var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) # 塗り専用のトークン hp.set_values(320, 500) # \"320 / 500\"",116],[8,"goslot-one-quick-slot","GoSlot — クイックスロット1つ",1,"GoSlot GoSlotGrid アイコン、個数、クールダウン、ショートカットを1つの面に収める。小さな円にバッジをぶら下げると、 スロットごとに幅が変わって列が揺れてしまう。 見える大きさと押せる大きさは違う。 詰めて並べたスロットは 48dp のタッチ領域が重なる。重なった分は 中心が近いほうのスロットが取る — touch_peers で互いの存在を教えておく。 keyboard_focus は既定で無効だ。8個並んだスロットが、キーボード利用者と設定項目すべての間に Tab 順で割り込まないようにするためである。キーボードやゲームパッドが唯一の入力手段なら有効にする。","",116],[8,"gojoystick-virtual-stick","GoJoystick — バーチャルスティック",1,"GoJoystick モード ふるまい FIXED 常に同じ場所 — 見なくても指が届く FOLLOW 親指を置いた場所に現れる RELATIVE 現れたあとも親指を追い続ける — 長く動かすときに楽だ moved が渡す Vector2 は長さ 0〜1 なので、そのまま速度に掛けられる。 画面サイズや DPI で変わることもない。","",116],[8,"goiconbutton-looks-small-presses-large","GoIconButton — 小さく見えて大きく押せる",1,"GoIconButton 安全なのは、隣が入力を受け取らないときだけだ。 広げた領域が隣のボタンに重なると、そのボタンは 反応しなくなる。並べて置くアイコンボタンには touch_peers が要る。","",116],[9,"gosnackbar-the-message-that-places-itself","GoSnackbar — 自分で居場所を決めるメッセージ",1,"GoSnackbar 画面の下（あるいは上）に、セーフエリアと仮想キーボードを避けて出て、自分で消える。これがないと、 「保存しました」と言うだけの画面ごとに、レイヤーも配置もタイマーも後片付けも書くことになる。 メッセージは互いを上書きせず順番に並ぶし、同じ文面の繰り返しはまとめられる — 毎秒4回失敗する サーバーが、4分ぶんの警告を積み上げることはもうない。ボタンのないスナックバーは入力を通すので、 その下のゲームは動き続ける。 何かを尋ねる場所ではない。 自分で消えてしまうので、プレイヤーが一度も見ないことがある。 取り消せない操作の確認は GoDialogs の仕事だ。ここに置くボタンは、なくても困らないものに限る — 取り消す、詳細、再試行。 GoNotice はこの対のもう半分だ。入力もフォーカスも決して取らず、どこに出すかは持ち主の画面が 決める。あちらはボタンを持てないが、こちらは持てる。","snack.show_text(\"保存しました\", GoTheme.SUCCESS) # 取り消す機会 — 0 は最初のボタン、-1 は時間切れ if await snack.post({\"text\": \"アイテムを捨てた\", \"actions\": [\"取り消す\"]}) == 0: restore_item()",-1],[9,"gospinner-a-wait-with-no-end-in-sight","GoSpinner — 終わりの見えない待ち時間",1,"GoSpinner.busy() · GoSpinner サーバーと話すゲームが、このページの中でいちばん必要とするものだ。止まったままの画面は、落ちたと 読まれる。呼び出し1つで、押されたボタンがその場でスピナーに変わる。 ボタンは大きさを保つ — ラベルは消えるのではなく透明になるので、行が跳ねない — そして回っている間は 無効になる。要はこの後半だ。await している間に購入が2回走ってはならない。 reduce_motion にすると回らず、代わりに3つの点が明滅する。 測れる進捗なら GoBar だ。スピナーは、いつ終わるかを何も約束しない。","GoSpinner.busy(buy_button, true) var ok := await server.purchase(item) GoSpinner.busy(buy_button, false)",-1],[9,"gobadge-the-unread-dot-the-new-tag-the-99","GoBadge — 未読の点、NEW の札、99+",1,"GoBadge アンカーで持ち主の右上に吊り下がるので、大きさが後から決まる相手にも付いていくし、2度付けても同じ バッジが返る。数が変われば行動も変わるときは数字を、「何かある」ことだけが問題なら点を使う。 文字の色は、スキンがバッジをどの色で塗ったとしてもコントラストが取れるように選ばれる — 白だと決めて かかることはない。読み上げ用の名前も持つ。色の付いた点は、スクリーンリーダーには何も伝えないからだ。","GoBadge.attach(mail_button, unread_count) # 0 のときは自分で隠れる GoBadge.attach(shop_button, 0, \"NEW\") GoBadge.attach(friend_button, 3, \"\", true) # 点 — 「何かある」",-1],[10,"gofield-the-row-that-can-be-wrong","GoField — 間違いを抱えられる行",1,"GoField · set_error() 入力欄が5つあるフォームの先頭に「入力を確認してください」と1行あっても、どの欄なのかは分からない。 その1点だけで、人は新規登録をやめてしまう。 エラーが出ている間ヒントは隠れるので、行が1行ぶん伸びて下のすべてを押し下げることがない。エラーの文は コントロールの読み上げ名にも連結される — 赤い枠だけでは、赤が見えない人には何も伝わらない。 GoStyle.field() は静的な版だ。ラベル、コントロール、ヒント、エラー状態なし。何も失敗しよう がないところはファクトリで、サーバーに断られうるものはノードで作る。","var name_field := GoField.make(\"キャラクター名\", GoStyle.line_edit(\"2〜12文字\"), \"あとから変更できない\") name_field.set_error(\"その名前は使われている\") # サーバーが断った name_field.clear_error()",-1],[10,"goinputgroup-an-input-welded-to-its-button","GoInputGroup — ボタンと溶接された入力欄",1,"GoInputGroup これが解くのは角の問題だ。丸い形が2つ真ん中で出会うとくびれて見えるし、既定の隙間があると2つの物体と して読めてしまう。外側の角は丸いまま、触れ合う角は四角にする — それをボタンのどの状態でも行う。さもないと、 押した瞬間にグループが割れる。面取りのスキンにはそもそも角の項目がないので、そこでは何も触らず、四角い 面どうしがきれいに合わさる。","GoInputGroup.make(GoStyle.line_edit(\"メッセージ\"), {\"suffix\": GoStyle.icon_button(&\"send\", send)}) GoInputGroup.make(GoStyle.line_edit(\"名前\"), {\"prefix_icon\": &\"search\"})",-1],[10,"gocombobox-a-picker-that-searches","GoCombobox — 検索できるピッカー",1,"GoCombobox 項目が10個までなら GoStyle.select() のほうがよい。タップが1回少なく、リスト全体が見える。 30 を超えると、目で追うこと自体が作業になる。 検索は名前の先頭だけでなく、途中にも一致する。 前方一致では、日本語や韓国語のリストはほとんど 引っかからない。2つの項目を見分ける語が先頭に来ることは、めったにないからだ。","var picker := GoCombobox.make(server_names, 0, \"サーバーを選ぶ\") picker.picked.connect(func(i: int) -> void: connect_to(servers[i]))",-1],[10,"gocodeinput-coupon-and-gift-codes","GoCodeInput — クーポンとギフトコード",1,"GoCodeInput コードは打ち込まれるより、メッセージから貼り付けられることのほうがずっと多い。本物の入力欄を12個並べると、 貼り付けは最初のマスで止まり、IME が文字を食う。だから文字を受け取るのは隠した1つの欄で、マスは描かれた ものだ。ABCD-EFGH-IJKL は、入るときにハイフンが落ちる。","var coupon := GoCodeInput.make(12, 4) coupon.completed.connect(func(code: String) -> void: server.redeem(code)) coupon.set_error(\"使用済み\")",-1],[10,"gotable-sortable-headers-selectable-rows","GoTable — 並べ替えできる見出し、選べる行",1,"GoTable numeric: true を忘れると、順位が逆さになる。 文字として比べると \"9124\" が \"91240\" に勝つ — スコアも所持金もダメージも、桁数はばらばらだ。 row_selected が渡すのは、並べ替え後の位置ではなく元の配列での添字だ。並べ替えの向きは色だけで なく記号でも示され、行は全体が押せるので、1つのセルを狙う必要はない。GoStyle.table() は 読み取り専用の表のまま残る。","var board := GoTable.make( [{\"text\": \"順位\", \"width\": 56}, {\"text\": \"名前\"}, {\"text\": \"スコア\", \"numeric\": true}], rows) board.row_selected.connect(func(i: int) -> void: open_profile(rows[i]))",-1],[10,"gopagination-pages-or-a-more-row","GoPagination — ページ番号、あるいは「もっと見る」の行",1,"GoPagination 番号はマウスの UI だ。スマートフォンなら「もっと見る」の行のほうが読みやすい。現在のページは窓の中央に 留まるので、次を押すたびに番号が全部並び替わることはない。合計 0 は「不明」を意味し、矢印だけが描かれる — 渡されていないページ数を、勝手に作り出したりはしない。","var pager := GoPagination.make(1, 12, func(page: int) -> void: load_mail(page)) var more := GoPagination.more(load_next) # スマートフォン向きの変種",-1],[11,"gorewardcalendar-daily-attendance","GoRewardCalendar — 毎日のログインボーナス",1,"GoRewardCalendar 日付ピッカーがゲームで役に立つことは、ほとんどない。カレンダーの形は役に立つ — ログインボーナスだ。 そこで問題になるのは何日目かであって、何月何日かではない。 押せるのは今日のマスだけだ — 押しても何も起きないボタンは、壊れていると読まれる。受け取り済み・今日・ これからの3つは、同時に3つの違いで見分けられる。チェックの記号、強調色の枠、そして暗さだ。","var attendance := GoRewardCalendar.make(days, claimed_until) attendance.claimed.connect(func(day: int) -> void: server.claim_day(day))",-1],[11,"goradar-and-godonut-stats-at-a-glance","GoRadar と GoDonut — ひと目で分かるステータス",1,"GoRadar GoDonut レーダーの値が 0〜1 なのは、どこを満点とするかがゲームの決めることだからだ — 素の STR 120 を INT 45 の 隣に置けば、嘘の形が描かれる。ドーナツの値は素のままでよく、割り算はこちらでやる。5つを超えた分はまとめ られる。6枚目の扇形は、誰にも読めない糸になるからだ。比較の線は色違いではなく破線で、凡例には 割合が文字で出る。","var stats := GoRadar.make({\"STR\": 0.85, \"AGI\": 0.5, \"INT\": 0.3, \"VIT\": 0.7, \"LUK\": 0.45}) stats.set_compare(with_new_sword) # 破線の重ね描き var share := GoDonut.make([{\"label\": \"物理\", \"value\": 620}, {\"label\": \"魔法\", \"value\": 340}]) card.add_child(share.legend())",-1],[11,"gocarousel-banners-and-character-select","GoCarousel — バナーとキャラクター選択",1,"GoCarousel 頼まない限り自分では進まないし、5秒が下限だ。3秒ごとに変わるバナーは、読み終える前に文字を持ち去る。 触れるとタイマーは戻り、reduce_motion にすれば自分から進むことは一切ない。点は小さく描かれる が、押せる範囲はタッチの最小寸法を保つ。","banners.set_pages([promo, event, pack]) banners.autoplay_seconds = 5.0 # 既定では動かない",-1],[11,"gokbd-key-hints-that-do-not-lie","GoKbd — 嘘をつかないキー表示",1,"GoKbd 直接書き込んだ「F を押す」は、プレイヤーが割り当てを変えたあとも F と言い続ける — PC の UI でいちばん よくある嘘だ。for_action() は InputMap を読む。その操作がパッドに割り当てられて いれば空を返してウィジェットは隠れる。「なし」もまた1つの嘘だからだ。Android と iOS では自分から隠れる。","hint.add_child(GoKbd.for_action(&\"interact\")) # 実際の割り当てを読む",-1],[12,"godrawer-the-side-panel","GoDrawer — 横から出るパネル",1,"Side.LEFT Side.RIGHT GoSheet は下から出る。縦に持ったスマートフォンにはそれが正しい。タブレットやデスクトップでは、 同じシートがゲームを覆ってしまう。ドロワーは代わりに横から出る。 パネルは画面の端まで届くが、中身はセーフエリアの内側に留まる。そうしないと、丸めた角が最初の行を切り 落とす。LEFT はアラビア語でも画面の左だ。「始まりの側」であることが要点なら follow_text_direction を有効にする。RTL では左右が入れ替わる。","bag.side = GoDrawer.Side.RIGHT bag.open(\"かばん\")",-1],[12,"gopopover-the-anchored-card","GoPopover — 脇に留まるカード",1,"GoPopover GoSurface の脇に留まる配置に、レイヤーもサーフェスもアンカーも後片付けも配線済みの ものだ — どのゲームも何度も書く、あの10行である。開くのは一度に1つだけだ。カードが積み重なると画面が埋まり、 どのカードがどのスロットのものか分からなくなる。幕は透明だ。装備を見比べるために開いたカードが、その装備を 暗くしてはならない。 ホバーのツールチップではない。 タッチにホバーはない。マウスでしか現れないものは、プレイヤーの半分 には見えないままだ。","GoPopover.open(slot, item_card(item))",-1],[12,"gocontextmenu-long-press-and-right-click","GoContextMenu — 長押しと右クリック",1,"GoContextMenu PopupMenu はエンジンにすでにある。ないのはジェスチャーのほうだ。開くまで 0.5 秒、 指が動いた瞬間に取り消す。だからリストをスクロールしてもメニューは出てこない。項目が「どれを押したか」 で変わるなら、配列の代わりに Callable を渡す。 長押しには、もう1つの入り口が要る。 隠れたジェスチャーは誰にも見つけられない — 目に見える ⋯ ボタン（open_at()）や、アイコンや、初回のコーチマークと組み合わせる。","GoContextMenu.attach(item_slot, [ {\"text\": \"使う\", \"action\": use}, {\"separator\": true}, {\"text\": \"捨てる\", \"action\": drop, \"danger\": true}, ])",-1],[12,"goconsole-the-developer-console","GoConsole — 開発者コンソール",1,"GoConsole チートとデバッグのコマンドだ。打つそばから絞り込むパレットが付くので、覚えておく必要はない。履歴は 矢印キーに載っている。すべての上に出るので、ダイアログの上からでもデバッグできる。 リリースビルドでは開かない。 debug_only は既定で有効だ。チートコマンドがプレイヤーの手に 渡れば、ゲームの経済は初日で終わる。","console.register(\"give\", \"アイテムを与える: give <id> <count>\", give) console.toggle()",-1],[13,"list-rows-with-a-description","説明の付いたリスト行",1,"GoStyle.list_button() 2行目のある行は上下の余白が等しくなり、1行の行より広めにとられる。タイトルと説明の組は アイコンの脇で上下中央に保たれる — コンテナが行を縦に引き伸ばしたときも、説明が複数行に折り返した あとも同じだ。行全体は1つのタップ対象のままである。 中世サンプルの2行リスト、スロット、バー — medieval_light の下での、同じファクトリ呼び出し。","GoStyle.list_button(GoIconSet.SWORD, \"誓いの剣\", _inspect, Color.TRANSPARENT, \"ロングソード / 攻撃力 42\", false)",-1],[13,"flowing-rows","折り返して流れる行",1,"row() · wrap_row() コントロールは自然な幅のまま wrap_row に入れる。折り返しを有効にしたままだと、 ボタンの最小幅はほとんど 0 まで落ち、行はその値でセルの大きさを決めてしまう — ラベルが1文字ずつ改行される。 ファクトリがこれを防いでくれる。","",-1],[13,"never-leave-an-empty-list-empty","空のリストを空のまま見せない",1,"skeleton() · empty_state() 人は何もない画面を壊れていると読む。","page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"まだ何もない\"))",-1],[13,"hooks","継承用のフック",0,"子ウィジェットを作るところはすべて上書き可能なメソッドを通る。だから gohud の型を継承したプロジェクトは、 コードを複製せずに自分のサブクラスをウィジェットの内側へ入れられる。 フック ウィジェット 既定 _make_scroll() GoCoachMark, GoSurface GoScroll.new() _make_close_button() GoPromptCard, GoSurface GoIconButton.new() _make_surface() GoSheet, GoDialogs GoSurface.new() _should_pause() GoCoachMark モーダルが開いている間はカードを隠す","",-1],[15,"pick","選ぶ",0,"この1行でテーマ・スキン・アイコンが入れ替わる。エディタからは プロジェクト設定 → Gohud → Theme → Preset、設定リソースからは GoConfig.preset で指定する。","GoUi.use_preset(GoThemePresets.SCIFI_DARK)",-1],[15,"keeping-one-field-your-own","1つだけ自分のものを使う",1,"theme・skin・icons を明示的に設定すると、プリセットより優先される。","GoUi.use_preset(GoThemePresets.SCIFI_DARK) GoUi.config.icons = my_icons # アイコンだけ自前、ほかはプリセットのまま",143],[15,"the-six-built-in-presets","組み込みの14プリセット",1,"プリセット パネル スキン · アイコン default_dark · default_light 段階的な影を持つ丸い StyleBoxFlat のパネル。主ボタンは押すと沈み、離すと持ち上がる GoSkin · デフォルトアイコン84種 scifi_dark · scifi_light ネオンの縁と発光を持つ面取りの GoStyleBoxCut パネル。フォーカス印は GoStyleBoxBracket GoSkinSciFi — 六角形のスティック · デフォルトアイコン medieval_dark · medieval_light 鍛造した GoStyleBoxMedieval の枠 — 鉄と革、あるいは羊皮紙 — にリベットと角飾りをメニューだけへ GoSkinMedieval · デフォルトの上に彫刻風16種 material_light · material_dark 新登場 アプリ画面向けの Material 3 Expressive — 48dp のタッチ領域に 40dp のピル型ボタン、28dp のダイアログ、塗りのカード、アウトラインの入力欄、Expressive のスライダー。アプリ部品(ナビゲーションバー・アプリバー・FAB・検索バー・チップ・進捗・日付選択)は M3 のコンポーネントトークンに従う GoSkinMaterial · デフォルトのアイコン kids_light · kids_dark 新登場 子ども向け — おもちゃ箱：太い縁取りと、押すと沈むしっかりした段のあるキー、くぼんだ入力欄、泡のタブ、ゼリーのバー、部品ごとに違うクレヨンの色、キャンディのクイックスロット、ステッカーのバッジ、虹色のジョイスティックとクレヨン色のチャート。サイズとプロジェクトのフォントはそのまま。 GoSkinKids · デフォルトのアイコン arcade_light · arcade_dark 新登場 GoStyleBoxArcade が描くアーケード筐体：どのキーも上から下へのグラデーション、白い光沢、押すと沈む段で塗られて紺色のインクの輪郭に収まり、ラベルはインクで縁取った白い文字 — プライマリは緑、キーは青、危険は赤、小さなキーはラベンダー色。ボードは淡い内側を色の枠で囲んだ厚いもので、ウィンドウには金色のタイトルバナーと丸い赤の閉じるキー。 GoSkinArcade · デフォルトのアイコン comic_light · comic_dark 新登場 GoStyleBoxComic が描くマンガのコマ：どの面にも太いインクの輪郭とくっきりした影があり、面を押すと影が消える。インクで描いたトグル、チェックボックス、スライダーのつまみ、ウィンドウには黄色のタイトルキャプション。輪郭の太さ、影の大きさ、影を出すかどうかは GoConfig の設定だ。 GoSkinComic · デフォルトのアイコン","",143],[15,"all-looks","14種類を並べて",0,"プリセット名だけを変えた同じギャラリー画面だ — ウィジェットのコードは1行も違わない。 どれも縦に持ったスマホ、390×844 だ。 default_dark default_light scifi_dark scifi_light medieval_dark medieval_light material_light material_dark kids_light kids_dark comic_light comic_dark arcade_light arcade_dark","",-1],[15,"medieval","中世 — 鉄、革、そして羊皮紙",0,"medieval_dark は暗い鉄と革にアンティークゴールドを合わせる。medieval_light は羊皮紙とインクを使う。どちらも GoSkinMedieval と既存のウィジェット、そして彫刻の描き込みを入れた オリジナルアイコン16種を使う。ナビゲーション用のアイコンは元のセットに落ちる。 プリセットは UI を作る前に選ぶ。GoConfig.theme・skin・icons を 明示的に指定した場合は、そちらが優先されたままだ。 res://addons/gohud/examples/medieval/medieval.tscn を開いて F6 を押せば、動くキャラクターシート・ 雑嚢・クエストジャーナルが見られる。ボタンでバリアントを切り替え、アイテムの詳細を開ける。 鉄と革 羊皮紙とインク メニューの枠にはリベットと小さな角飾りがあり、常に見えている HUD は縁を静かに保つ。 体力・マナ・スタミナは赤・青・オリーブで塗る。Cinzel はタイトルとサブタイトルに限って使い、 本文はホスト側またはデフォルトのフォントのままだ。同梱フォントのライセンスは assets/fonts/cinzel/OFL.txt にある。 彫刻セットが描き直すのは bag、book、box、coin、crown、 flag、heart、key、map、potion、shield、 star、sword、user で、さらに scroll と seal を足す。 それ以外の名前はデフォルトセットに落ちるので、close や settings はどのプリセットでも 同じ絵のままだ。Cinzel が持つのはラテン文字なので、各言語の見出しには shape.fonts から 専用のフォントを与える。 テストスイートが両バリアントで確かめること。 中世スキンが選ばれていること。メニューと HUD のパネルが 鍛造の枠で、角飾りはメニューにだけ付くこと。タイトルが Cinzel を使い、本文は継承したフォントを保つこと。 彫刻アイコンが DPITexture としてインポートされること。実物のクイックスロットがスキンを使うこと。 複製したスキンのダイヤルを変えると、プリセットに触れずにスロットへ届くこと。そして戻したときに、 デフォルトと SF のジオメトリが復元されること。","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # または: GoUi.use_preset(GoThemePresets.MEDIEVAL_LIGHT)",-1],[15,"make-a-kingdom-of-your-own","自分だけの王国を作る",1,"JSON テーマは別の JSON テーマを継承できる。書かなかった値は親の設定をそのまま保ち、 循環する継承は拒否される。生成されたプリセットは親のアイコンセットを引き継ぐ。 設定 効果 shape.material 0: 鉄 · 1: 革 · 2: 羊皮紙。表面の模様を決める。 shape.grain_alpha 質感の不透明度。0 にすると無地の面になる。 shape.ornament_scale · shape.bevel_strength メニューの角飾りの大きさと、ベベルのハイライトの強さ。 shape.fonts title・subtitle・caption・body・button の役割を、アドオン内の res:// フォントファイルへ割り当てる。書かなかった役割は継承したフォントのままだ。 skin.dials クイックスロットの角丸、リベットの表示、質感、ハイライト。ダイヤルの全一覧は下の表にある。","python3 addons/gohud/tools/new_theme.py kingdom --from medieval_dark # themes/palettes/kingdom.json を編集してから: python3 addons/gohud/tools/make_theme.py kingdom godot --headless --path . --import # GDScript では、ウィジェットを作る前に: GoUi.use_preset(&\"kingdom\")",147],[15,"material","Material 3 — アプリ画面のための見た目 新登場",0,"material_light と material_dark は Material 3 Expressive を gohud に持ち込む — M3 コンポーネントの 形・大きさ・文字組みを、すべての数値を公式の M3 トークンセット（material-web、 tokens/versions/latest）から読んで再現した。ゲームのメニューよりもアプリらしく見せたい画面に使う： ショップ、受信箱、アカウントや設定のページ、ランキング、コンパニオンアプリ。 material_light material_dark GoDialogs · material_light GoDialogs · material_dark","GoUi.use_preset(GoThemePresets.MATERIAL_LIGHT) # または: GoUi.use_preset(GoThemePresets.MATERIAL_DARK)",-1],[15,"what-changes","変わるもの",1,"部分 Material 3 では ボタン ピル型（角は完全な丸）。下地は高さ 40dp で 48dp のタッチ領域の中央に置かれるので、押せる範囲は狭まらない。compact ボタンの下地は 32dp。ラベルはウェイト 500 の Roboto だ。 ダイアログとシート 28dp の角（extra-large）、24dp の内側余白、24sp の見出し — GoDialogs、GoSurface、GoSheet、そしてその上に作られたすべてのポップアップ。 カード 12dp の角と 16dp の内側余白を持つ塗りのカード。 入力欄とスライダー アウトラインのテキスト入力欄。背の高いハンドルを持つ Expressive のスライダー。 チップとセグメント選択 8dp の角（small）。 アプリ部品 GoNavBar、GoAppBar、GoFab、GoSearchBar、チップ、GoProgress、GoDatePicker は M3 のコンポーネントトークンに従う。 文字 タイトル、サブタイトル、キャプション、ボタンには同梱の Roboto を使う。本文はプロジェクトのフォントのままなので、韓国語・日本語・中国語・アラビア語もそのまま描ける。 不透明度 すべてのパネルが不透明だ — M3 のサーフェスはベタ塗りだからだ。（デフォルト、SF、中世のパネルは不透明度80%なので、ゲームが透けて見える。） スキン GoSkinMaterial：ドロワーは M3 のモーダルサイドシート、コンソールの面は M3 のフローティングツールバーで、バナーは surface_container_low の上に載る。 仕様が読みやすさに道を譲るところ。 M3 は無効なラベルを38%まで薄くするが、gohud は読めるように 4.5:1 を 保つ。スナックバーは明るい下地のままにしてある — 文字の色はウィジェットが選ぶトークンなので、反転した下地では暗い地に 暗い文字が載ってしまう。tools/check_contrast.py は、この2つの見た目もほかのすべてと同じように測る。 Roboto は SIL Open Font License 1.1（assets/fonts/roboto/OFL.txt）で提供されており、Material プリセットだけが使う。","",149],[15,"kids","キッズ — おもちゃ箱 新登場",0,"kids_light（クリームとピーチの地にぶどう色のプライマリ）と kids_dark（ブルーベリーの地、 お日さま色のプライマリ、ミントのピル）は、子ども向けのゲームや学習アプリのために作った見た目だ — ぽってりして、明るくて、 ぷにぷにで、小さな指が思わず押したくなるもの。 kids_light kids_dark GoDialogs · kids_light GoDialogs · kids_dark","GoUi.use_preset(&\"kids_light\") # または: GoUi.use_preset(&\"kids_dark\")",-1],[15,"what-changes-2","変わるもの",1,"部分 キッズの見た目では すべての面 GoStyleBoxJelly が描くゼリーキャンディ：太い縁取り、押せるものすべての下にあるしっかりした段、上が明るく下が濃い本体、左上の白いつや。キー、リストの行、折りたたみの見出し、入力欄、バー、スライダー、パネルがみなこれをまとう。 押したとき 段が消えて面がその位置へ沈み、続いてゼリーのようにぷにっとつぶれる — 一瞬横に広く平たくなり、弾むように戻る。gohud が作るすべてのボタンで動き、reduce_motion で止まる。 入力欄、タブ、バー テキスト入力欄は同じゼリーを内側に返したもの — くぼんだ井戸だ。タブは泡、バーにはゼリーのつやがある。 色 部品の種類ごとに自分のクレヨンの色をまとう。ほかのすべての見た目と同じ生成器が選ぶので、コントラストの関門はすべて通ったままだ。 ウィンドウ ウィンドウのタイトルの後ろにお日さま色のリボン（夜はミント）— タイトルは1行に収まるよう15まで縮む — と、危険のクレヨン色に白い×を描いた丸いキャンディの閉じるボタン。 スキンの部品 GoSkinKids：クイックスロットはクールダウン中に沈むキャンディのブロック、バッジはステッカー、チップとナビゲーションのピルは小さなゼリー、アバターは丸いキャンディ、スティックは虹色、チャートはクレヨン、アラートと通知はしっかりした縁のステッカーメモだ。 不透明度 パネル、カード、通知、ポップアップは不透明だ。 サイズは変わらない。 縁取りと段は各コントロールの矩形の内側に描かれ、どの面もテーマが与えた内側余白を保つので、 別の見た目でレイアウトした画面はそのままのレイアウトを保ち、自前でサイズを固定したホストも同じ部品を測ることになる。 プロジェクトのフォントもそのままなので、ラテン文字以外の文字もそのまま描ける。 スキンが描く部品 — キッズの行は2番目","",151],[15,"make-a-toy-box-of-your-own","自分だけのおもちゃ箱を作る",1,"","python3 addons/gohud/tools/new_theme.py candy --from kids_light # themes/palettes/candy.json を編集してから: python3 addons/gohud/tools/make_theme.py candy GoUi.use_preset(&\"candy\")",151],[15,"comic","コミック — 太いインク 新登場",0,"comic_light（紙のようなクリーム色のページに白いパネル、コバルトのプライマリ）と comic_dark（夜のページに スレート色のパネル、クリーム色の輪郭、黄色のプライマリ）は、どの面もマンガのコマのように描く — 太いインクの輪郭の後ろに くっきりした影を落とす。 comic_light comic_dark GoDialogs · comic_light GoDialogs · comic_dark","GoUi.use_preset(&\"comic_light\") # または: GoUi.use_preset(&\"comic_dark\")",-1],[15,"what-changes-3","変わるもの",1,"部分 コミックの見た目では すべての面 GoStyleBoxComic が描く：インク色の太い輪郭の中に表面の色を塗り、右下へくっきりした影を落とす。キー、リストの行、入力欄、タブ、バー、スライダー、パネル、ポップアップがみなこれをまとう。 押したとき 影が消えて、面がその位置へ沈む。 コントロール トグル、チェックボックス、ラジオボタン、スライダーのつまみもインクで描かれ、それぞれに小さな影が付く。 ウィンドウ ウィンドウのタイトルの後ろに黄色のキャプションと、インクで描いた丸い閉じるボタン。 スキンの部品 GoSkinComic：クイックスロット、チップ、バッジ、アバター、通知、ナビゲーションバー、FAB、日付のセルがインクで描かれ、スティックのノブは影を落とし、チャートは太い原色を使う。 不透明度 パネル、カード、通知、ポップアップは不透明だ。HUD カードは 92% 不透明。","",154],[15,"ink-and-shadow-settings","インクと影の設定",1,"GoConfig の3つの設定が、すべてのコミックの面を一度に変える。作り直すものは何もない — 値を入れたそばから画面が描き直される。 ウィジェット1つだけなら、設定に関係なく独自の道を行ける： サイズは変わらない。 輪郭と影は各コントロールの矩形の内側に描かれ、どの面もテーマが与えた内側余白を保つので、 別の見た目でレイアウトした画面はそのままのレイアウトを保つ。プロジェクトのフォントもそのままだ。 コミックスキンが描く部品","GoUi.config.comic_border_width = 2.0 # 輪郭 (dp) — 既定は 3 GoUi.config.comic_shadow_size = 6.0 # 影 (dp) — 既定は 4 GoUi.config.comic_shadow = false # どこにも影を出さない GoStyle.comic_shadow(skip_button, false) # このボタンは平らに GoStyle.comic_shadow(card, true, true) # このカードとその中身すべては影を保つ GoStyle.comic_border(title, 5.0) # これだけ輪郭を太く",154],[15,"make-a-comic-of-your-own","自分だけのコミックを作る",1,"","python3 addons/gohud/tools/new_theme.py inked --from comic_light # themes/palettes/inked.json を編集してから: python3 addons/gohud/tools/make_theme.py inked GoUi.use_preset(&\"inked\")",154],[15,"arcade","アーケード：塗られたキーと厚いボード 新登場",0,"arcade_light（空色のページに白いボード）と arcade_dark（夜のページに紺色のボード）は、 どの画面もアーケード筐体のように仕立てる：どのキーも塗られている — 上が明るく下へいくほど深くなるグラデーション、 白い光沢のひと筋、押すと沈む段を紺色のインクの輪郭に収める — そしてどのボードも厚い。淡い内側を 色の枠が囲む。 arcade_light arcade_dark GoDialogs · arcade_light GoDialogs · arcade_dark","GoUi.use_preset(&\"arcade_light\") # または: GoUi.use_preset(&\"arcade_dark\")",-1],[15,"what-changes-4","変わるもの",1,"部分 アーケードの見た目では キー GoStyleBoxArcade が描く：グラデーションの本体、左上の角を回り込む白い光沢、より深い色の段、紺色のインクの輪郭。プライマリキーは緑、普通のキーと選ばれたタブは青、危険なキーはコーラル色と赤、小さなキーとほかのタブはラベンダー色だ。 ラベル 塗られたキーにはどれも、インクで縁取った白い文字。どの塗りも、そのラベルがグラデーションのどの高さでも読めるまで調整される — WCAG と同じく縁取りを文字の一部として数え、4.6:1 以上。 押したとき 段が消え、キーがその位置へ沈んで、また跳ね返る。 ボード パネル、カード、HUD カード、ポップアップは厚い：自分の光沢と段を持つ色の枠（ウィンドウは 6dp、カードと HUD カードは 4、メニューと通知は 3）が、インクの線で縁取った淡い内側を囲む。これを収めるために内側余白が少し広がるので、文字が枠に触れることはない。 入力欄とバー 入力欄とバーの溝はくぼんだ内側だ。バーの塗りは、その色の明るい塗り色で塗った光沢のあるチューブ。 ウィンドウ インクで縁取った白いタイトルを載せた金色のバナーと、白い×の入った丸い赤の閉じるキー。 スキンの部品 GoSkinArcade：クイックスロットとチップはキーキャップで、クールダウン中のスロットには金の縁が灯り、バッジは明るいプレート、アラートは自分の色の枠で囲まれ、選ばれたカードには金の縁が灯る。FAB は金色のキー、スティックは4つの矢印の付いた光沢のあるパッドだ。 不透明度 パネル、カード、通知、ポップアップは不透明だ。HUD カードは 94% 不透明。","",158],[15,"paint-one-key-its-own-colour","キー1つを自分の色で塗る",1,"テーマはキーを種類ごとに塗る。キーごとに自分の色を持たせたいメニューは、1つずつ塗ればいい — ホバーの面は少し明るく、 押した面は少し深くなり、無効の面はくすんだままだ： ラベルはいつでも読める。 白いラベルが読めない塗りは、読めるようになるまで明るく、または深く調整されるので、 渡した色は出発点にすぎない。ほかの見た目では arcade_paint() は何もしない。 キーの大きさは変わらない。 段と光沢は各キーの矩形の内側に描かれるので、別の見た目でレイアウトした画面は そのままのレイアウトを保つ。ボードは文字が枠に触れないよう、中身に少しだけ多く余白をとる（カードと HUD カードは 12dp、 下は 15）。プロジェクトのフォントもそのままだ。 アーケードスキンが描く部品","menu.add_child(GoStyle.arcade_paint(GoStyle.button(\"Resume\", _resume, GoStyle.Tone.PRIMARY), Color(\"#4ACB3E\"))) menu.add_child(GoStyle.arcade_paint(GoStyle.button(\"Shop\", _shop), Color(\"#FF8A1E\"))) GoStyle.arcade_paint(stage_card, Color(\"#E3343D\"), true) # ボードの枠と、その中のすべてのキー",158],[15,"make-an-arcade-of-your-own","自分だけのアーケードを作る",1,"","python3 addons/gohud/tools/new_theme.py cabinet --from arcade_light # themes/palettes/cabinet.json を編集 — *_vivid の色が塗りの色だ — してから: python3 addons/gohud/tools/make_theme.py cabinet GoUi.use_preset(&\"cabinet\")",158],[16,"colours","色",1,"名前 使いどころ background 画面の地 surface · surface_soft · surface_high パネルの3層 — パネル、カード、浮いたセル border カードとボタンの枠 text · secondary · muted 文字の3段階 — 本文、補助、控えめ accent · on_accent アクセント色と、その上に載せる文字の色 success · warning · danger · info 状態を表す文字の色 *_fill 同じ状態を塗りとして使う色 — バーなど面積の大きい場所 scrim · shadow · track ポップアップ背後の幕、影、バーの溝 *_fill がある理由。 意味は同じでも、求められるものが正反対だからだ。warning は文字として使うなら明るい背景で読める程度に暗くなければならず、経験値バーの塗りとして使うなら目に留まる 程度に明るくなければならない。1つのトークンで両方は満たせない — 実際にライトテーマのバーは茶色になった。 _fill を持たないテーマは自動で元の名前に落ちるので、これらのトークン以前のテーマもそのまま動く。","",-1],[16,"measurements-dp","寸法(dp)",1,"touch button_height gap_tiny gap_small gap gap_large padding padding_compact compact_padding_x compact_padding_y radius_small radius radius_large screen_margin scroll_deadzone scroll_edge scrollbar_width list_glyph icon_size notice_duration_ms","",-1],[16,"panel-opacity","パネルの不透明度(%)",1,"panel_alpha card_alpha hud_alpha notice_alpha popup_alpha — コンテナの面がどれだけ不透明か。既定は 80 で、ダイアログの背後でも ゲームは見えたままだ。popup_alpha だけは 100 だ。これらのトークンを持たないテーマは 100 に 落ちるので、これまでとまったく同じに描かれる。解決された値は GoUi.surface_alpha(variant) で比率として読める。規則は 不透明度 — パネルの向こうのゲーム の節にある。","",-1],[16,"text-roles","文字の役割",1,"micro · compact · caption · body · button · subtitle · title — 役割が指すのは大きさであって 用途ではない。「見出し」ではなく「いちばん大きい文字」だ。そうしておけば、ある画面がそれを別の目的で 使っても尺度は崩れない。","",-1],[16,"type-variations","タイプバリエーション",1,"GoPanel GoCard GoButton GoPrimaryButton GoDangerButton GoDangerSolidButton GoPrimaryGlowButton GoDangerSolidGlowButton GoBareButton GoCompactButton GoIconButton GoListButton GoTitleLabel GoSubtitleLabel GoCaptionLabel GoCompactLabel GoMicroLabel","",-1],[17,"five-layers-most-specific-first","5つの層、具体的なものから順に",1,"順 どこ 単位 及ぶ範囲 ① その呼び出しの引数 — surface.alpha、GoStyle.card(…, alpha) 比率 0.0–1.0 1つのウィンドウ ② GoConfig.container_alpha_overrides[kind] 比率 0.0–1.0 1種類のパネル、プロジェクト全体で ③ GoConfig.metric_overrides[<kind>_alpha] パーセント 寸法をすべて1か所にまとめているプロジェクト ④ GoConfig.container_alpha 比率 0.0–1.0 すべてのパネルを一度に ⑤ テーマの GoHud/constants/<kind>_alpha パーセント 見た目が決めること — 大もとはここだ どれも設定しなければ値は 100 だ。だから古いテーマは何も変わらない。 不透明度はどこでも比率だ — テーマの中だけが例外だ。 alpha という名のフィールドも 引数も、すべて 0.0–1.0 を取る。Color.a や modulate.a と同じ単位で、負の値は 「設定なし」を意味する。唯一の例外はテーマの定数だ。Theme の定数は小数を持てないからで、 その定数と、それを上書きする経路（テーマと同じ名前と整数型を共有する metric_overrides）だけが 80 と書かれる。ほかはどこもそうではない。","# 1つのウィンドウだけ — 背後の戦いを隠してはならない確認ダイアログ surface.alpha = 0.6 sheet.alpha = 0.7 dialogs.alpha = 0.9 # @export のフィールドも比率だ drawer.alpha = 0.7 GoPopover.open(slot, body, {\"alpha\": 0.9}) var glass := GoStyle.card(Color.TRANSPARENT, -1.0, -1.0, -1.0, 0.5) # 種類ごと — HUD はほぼ不透明に保つ。その文字は世界の上に直接載るからだ GoUi.config.container_alpha_overrides = { GoTheme.BOX_PANEL: 0.7, # ダイアログとシートは息をつける GoTheme.BOX_HUD: 0.95, } GoUi.refresh() # すでに開いているウィジェットを描き直す # プロジェクト全体 — 情報の多い世界では、パネルを不透明に戻したくなる GoUi.config.container_alpha = 1.0 GoUi.refresh() GoUi.surface_alpha(GoTheme.BOX_PANEL) # 解決された比率。たとえば 0.8",-1],[17,"what-follows-the-value-and-what-does-not","この値に従うもの、従わないもの",1,"従うもの — コンテナ 無視するもの — 押すもの、そして印 GoSurface（ダイアログ、シート、ドロップダウンの背後にある唯一の外殻） · GoSheet · GoDialogs · GoDrawer · GoPopover · GoNotice · GoSnackbar · GoPromptCard · GoCoachMark · GoConsole すべてのボタン · GoSlot（クイックスロット） · GoBadge · セグメント選択 · 選択セル · チップ · 円とアバター GoStyle.card() · hud_panel() · overlay_panel() · alert() · plate() · edge_card_panel() · style_notice_panel() · floating() · box() · surface() すべての文字とアイコン 状態が薄れたボタンは、自分が何であるかをもう伝えない。バッジは2文字を読ませるために存在する — どちらもコンテナではないから、どちらもこの値には従わない。 ポップアップメニューは不透明のままだ（popup_alpha は 100）。エンジンは PopupMenu を独立した Window に載せることがあり、そこでは OS がゲームと 合成してくれない — 半透明は透けるのではなく黒く出る。下げてよいのは、サブウィンドウを埋め込んでいる プロジェクト（gui_embed_subwindows）だけだ。","",-1],[17,"three-details-that-come-from-real-screens","実際の画面から分かった3つのこと",1,"この値は掛かるのであって、置き換えるのではない。 既定の HUD の面はすでにアルファ 0.92 だから、 hud_alpha 80 は 0.736 に着く — 面をわざと半透明にしたテーマは、その判断を保つ。 裏を返せば、2回かければパネルは2回薄くなる。だからアルファを掛けるのはただ1か所 （GoSkin.surface_box()）だけで、ほかの面を作る関数はどれも、自分の結果を薄めずに 引数をそのまま渡す。 渡した色は、渡したとおりに返る。 GoStyle.plate(…, fill) は、明示された塗りを 与えられたまま保つ。Color(ink, 0.14) はすでに自分のアルファを述べていて、そこへパネルの 不透明度を掛ければ、呼び出し側の意図を二重に削ることになる。 GoStyle.floating(…, opaque = true) が同じたぐいの理由でこの値を無視する — 面を不透明に塗りつぶすことが、そのフラグの目的そのものだからだ。 gohud が作ったのではないパネルにも、同じ規則が及ぶ。 GoStyle.fade_panel(node) — ノードがツリーに入ったあとで呼ぶ。そうすれば、継承したテーマを読める。この関数は冪等だ。元の面を 記録しておき、呼ぶたびにそこから計算し直すので、描き直しを繰り返しても効果が積み重なることはない。 テーマを差し替えたあとは GoStyle.forget_face(node) でその記憶を捨てる。すると次の 呼び出しが新しい面を拾う。","",-1],[17,"custom-faces-fade-too-and-that-is-the-part-that","独自の面も薄くなる — そして、黙って壊れるのはここだ",1,"面取りのパネル（GoStyleBoxCut）と鍛造の枠（GoStyleBoxMedieval）は StyleBoxFlat ではない — 自分で描く。不透明度をフラットの枝にだけ入れると、これらの テーマは黙ってそれを無視し、それでいて値を見るテストはすべて通ってしまう。どちらも背景を薄くし、 発光、リベット、角の彫刻、ベベルは強さを保つ。そして中世の面の質感とベベルはもともと背景のアルファに 比例していたので、パネルと一緒に薄くなる。 ここから広い話になる。bg_color.a == 0.8 は数値にすぎない。世界が透けて見え、それでも 文字が読める — これが要件だ。gohud は前者をヘッドレスの検査で確かめ、後者を仮想モニタ上で斜めの縞 の上にパネルを描いて確かめる（tests/gohud_alpha_shot.gd）— フラットの面、面取りの面、 鍛造の面で、ダークとライトの両方のテーマで。","",-1],[18,"shapes-styleboxflat-cannot-make","StyleBoxFlat では作れない形",1,"クラス 描くもの GoStyleBoxCut 斜めに切り落とした角、1辺だけ太いアクセント縁、外へにじむ発光 GoStyleBoxBracket 四隅の印だけを引き、中身は囲わない GoStyleBoxMedieval 鍛造の枠 — リベット、角の彫刻、ベベルのハイライト、そして鉄・革・羊皮紙の質感 3つともほかの StyleBox と同じように Theme リソースへ保存される — だからテーマが形まで変えられる。 余白は content_margin_* で与える。 GDScript で StyleBox を継承すると _get_style_margin() は呼ばれない（Godot 4.7 で実測）。組み込みのフィールドを埋めないと、 中身が枠に貼り付いてしまう。","",-1],[19,"what-you-can-change-on-one-page","変えられるもの — 1ページで",1,"場所 何を どう書くか from 継承元のテーマ dark · light · scifi_dark · medieval_dark · … あるいは別の JSON テーマ。書かなかったキーはその値を継承し、循環すると失敗する palette 背景 · 3つのサーフェス · 枠 · 3段階の文字色 · アクセント · 4つの状態色 · 幕 · 影 · バーの溝 \"#RRGGBB\"、アルファ付きは \"#RRGGBB@0.35\" 塗り専用の鮮やかな色 *_vivid 文字色が暗くならざるを得ないときでもバーは鮮やかに保つ — 書き忘れるとビルダーが教えてくれる 読みやすさ 手で調整しない。 文字・枠・アクセント・その上のラベルは、しきい値を超えるまでビルダーが押し上げる — アクセントだけを変えても検査は通ったままだ shape kind flat（丸み） · cut（面取りした角） · medieval（鍛造の枠） 寸法 radius · radius_small · radius_large · gap · gap_small · gap_large · padding · button_height · button_padding[4] — トークンも一緒に動くので、パネルとウィジェットの計算が食い違わない cut 専用 cut_ratio · cut_max · corners(diagonal|all) · glow · edge medieval 専用 material（0 鉄 · 1 革 · 2 羊皮紙） · grain_alpha · ornament_scale · bevel_strength · fonts — title、subtitle、caption、body、button をアドオン内の res:// フォントファイルへ割り当てる skin base — コードが自分で描く場所（スティック、スロット、バッジ、コーチマークのリング、チップ、区切り線）の系統 default · scifi · medieval dials — それらの場所の数値。スロットの枠の太さと色味、バッジの余白、チップとアラートの不透明度、スティックのリングの太さと不透明度、SF の面取り寸法、発光とブラケット 親の値はすべて JSON に書き出される。ビルダーがそれを themes/skins/gohud_skin_<id>.tres へ書き込む — スキンのコードには触れない。描画そのものを変えたいときだけ --new-skin を付け、GoSkin のサブクラスの雛形を作らせる icons アイコンセット GoIconSet リソースへの res:// パス — 省略すると JSON の親から引き継ぐ dark · title 選択リストでの見せ方 真偽値 · 文字列","",-1],[19,"every-dial","ダイヤル一覧",1,"下の表は tools/make_site.py がスキンスクリプトの @export 行から直接読んで埋める — ダイヤルを足したり既定値を変えたりすれば、表も付いてくる。JSON の skin.dials の下では、この名前を使う。 既定値が 14 と書かれているダイヤルは整数、10.0 と書かれているものは浮動小数点数だ。 JSON にはどちらの形で書いてもよく、ビルダーがスクリプトの型に合わせて変換する。 デフォルトスキン GoSkin — 17 ダイヤル 既定値 設定する内容 chip_fill_alpha 0.16 チップのパネルの塗りの不透明度。 chip_edge_alpha 0.45 チップのパネルの縁の不透明度。 alert_tint 0.1 アラートボックスのパネルが状態色へどれだけ寄るか。 slot_tint_lit 0.24 クールダウン中のクイックスロットのパネルがアクセント色へ寄る度合い。 slot_tint_idle 0.08 平常時のクイックスロットのパネルがアクセント色へ寄る度合い。 slot_border_lit 2 クールダウン中のクイックスロットの枠の太さ(dp)。 slot_border_idle 1 平常時のクイックスロットの枠の太さ(dp)。 badge_pad_x 5 バッジ（個数・残り時間）の内側の横余白(dp)。 badge_pad_y 1 バッジの内側の縦余白(dp)。 badge_edge_alpha 0.6 バッジのパネルの縁の不透明度。 float_shadow_alpha 0.45 浮かぶカード（コーチマーク、プロンプトカード）の影の不透明度。 float_shadow_size 14 浮かぶカードの影のぼかし(dp)。 float_shadow_lift 4 浮かぶカードの影が下へずれる距離(dp)。 float_glow_size 10.0 SF の面取りパネルのように、影ではなく発光を使う浮かぶパネルの発光距離(dp)。 joystick_base_alpha 0.42 スティックの土台の円の不透明度。 joystick_ring_alpha 0.45 スティックのリングの不透明度。 joystick_ring_width 2.0 スティックのリングの太さ(dp)。 SF スキン GoSkinSciFi — 10 ダイヤル 既定値 設定する内容 cut_chip 7.0 チップのパネルの面取りの大きさ(dp)。 cut_skeleton 5.0 スケルトンのパネルの面取りの大きさ(dp)。 cut_alert 8.0 アラートボックスの面取りの大きさ(dp)。 cut_segment 8.0 セグメント選択の面取りの大きさ(dp)。 cut_slot 6.0 クイックスロットのパネルの面取りの大きさ(dp)。 cut_disc_ratio 0.24 アバターや円の面取り = 直径 × この比率。 slot_glow_alpha 0.45 クールダウンが回っているスロットの発光の不透明度。 slot_glow_size 6.0 クールダウンが回っているスロットの発光距離(dp)。 bracket_arm 12.0 コーチマークの照準ブラケットの腕の長さ(dp)。 bracket_thickness 2.0 コーチマークの照準ブラケットの線の太さ(dp)。 中世スキン GoSkinMedieval — 5 ダイヤル 既定値 設定する内容 slot_radius 4.0 中世のクイックスロットの枠の角丸(dp)。 leather_grain_alpha 0.035 クイックスロットの内側にうっすら入る革の模様の不透明度。 ornament_scale 1.0 クイックスロットの角に付く金属装飾の倍率。メニューの枠は shape.ornament_scale を使う。 bevel_strength 0.18 クイックスロットの縁に沿う金属のハイライトの強さ。 slot_rivets 1 クイックスロットに小さな金属リベットを出すか。0 で隠し、1 で表示。 Material スキン GoSkinMaterial — 2 ダイヤル 既定値 設定する内容 segment_gap 2.0 Material の連結ボタングループで、セル同士の間隔(dp)。 segment_inner_radius 8 Material の連結ボタングループで、2つのセルが接する角の丸み(dp)。 キッズスキン GoSkinKids — 3 ダイヤル 既定値 設定する内容 toy_edge 2 キッズのおもちゃ部品 — チップ、スロット、FAB、アラート — の縁取りの太さ(dp)。 toy_lip 4 キッズの押せるおもちゃ部品の下にあるしっかりした段(dp)。部品を押すと縮む。 crayon_tint 0.28 キッズのスロットやチップの面をクレヨンの色でどれだけ塗るか(0–1)。残りは表面の色。 コミックスキン GoSkinComic — 1 ダイヤル 既定値 設定する内容 comic_tint 0.22 コミックのチップ、クイックスロット、選択中のピルの面を、それ自身の色でどれだけ塗るか(0–1)。残りは表面の色。 アーケードスキン GoSkinArcade — 3 ダイヤル 既定値 設定する内容 arcade_edge 3 アーケードスキンが塗る部品 — スロット、チップ、バッジ、タイトルバナー、FAB — のインクの輪郭の太さ(dp)。 arcade_lip 4 アーケードの押せる部品 — キー、チップ、スロット、FAB — の下にある段(dp)。部品を押すと消える。 arcade_gloss 0.85 塗られたアーケード部品に入る白い光沢のひと筋の強さ(0–1)。","",-1],[19,"subclass-the-skin-optional","スキンを継承する（任意）",1,"スキンにあるのは、テーマと形では届かないものだけだ — スティックの六角形、スロットのバッジ、 コーチマークの照準ブラケット。GoSkin を継承してそれらのメソッドだけを上書きし、JSON の skin をそのリソースへ向ける。色だけのテーマなら、この手順はいらない。 約束を守らせるのは検査だ。 tools/check_scaffold.sh は実行のたびに使い捨てのテーマを作り — アクセントを変え、半径を 4 にして — 生成・トークンの伝播・コントラスト検査の通過までを確かめてから消す。 最初の実行では、アクセントだけを変えたテーマが8組で不足していた。ビルダーが文字色は押し上げるのに、 アクセントは書かれたまま使っていたのだ。いまはアクセントと、その上のラベルも押し上げる。","",-1],[20,"same-hue-text-on-a-same-hue-tint","同系色の文字を同系色の淡い面に載せる",1,"この落とし穴は、このコードベースで3度現れた — 押されたボタン（アクセントのパネルにアクセントの文字）、 危険ボタン、そしてチップだ。色見本の上ではよく見えるのに、測った瞬間に崩れる。 2つが同じ色相を共有していて、明度の差がないからだ。 だからラベルの色は手で選ばない。テーマのビルダーと GoSkin はそれぞれ、文字が実際に載る パネルの上でしきい値を超えるまで明度だけを押し上げる。色相と彩度は残るので、パレットは持ち味を保ち、 変更してもコントラストは保たれる。","",-1],[20,"colour-read-as-text-and-colour-painted-as-area-w","文字として読む色と、面として塗る色は求めるものが逆だ",1,"ライトテーマでは、警告色は文字として読めるよう暗くしなければならない(#96500A)。 バーの塗りがそれを受け継ぐと、経験値バーは茶色になる。色だけでは直せない。黄色はそもそも明るく、 灰色の溝に対して 3:1 をまったく満たさないし、溝を暗くするともっと悪くなる(1.52 → 1.06)。 そこで両者を切り離した。色は鮮やかなまま — パレットは warning_vivid のような 塗り専用の色を持つ。コントラストは縁が担う — GoSkin は、溝に対して 3:1 に届かない塗りに 1dp の輪郭を描く。こうして「どれだけ溜まっているか」は読めるままになる。 書き忘れは報告される。 *_vivid がないまま塗りが暗くなると、ビルダーは the bar looks drab — add warning_vivid to the palette と出力する（ビルダーが実際に出す文言）。 黙って劣化していた場所が、いまは声を上げる。","MY_LIGHT = dict( warning=hexc(\"9A5407\"), # 文字として読む色 warning_vivid=hexc(\"F2A007\"), # バーに塗る色 )",-1],[20,"a-floating-panel-cannot-know-what-is-behind-it","浮かぶパネルは、背後に何があるか知りようがない",1,"HUD はゲームの上に描かれる — 雪原かもしれないし、洞窟かもしれない。パネルが半透明なら背後のものが 透けてパネルの色そのものを変え、文字のコントラストまで道連れにする。不透明度 82% では、明るい背景の上で ダークテーマの控えめな文字が 3.74:1 まで落ちた — 最低基準を下回っている。 そこで半透明のパネルは純白と純黒を背後に置いて測る。ゲームの場面が出しうる最悪がその2つだからだ。 同梱テーマの HUD パネルは、ガラスのような見え方を保ったまま基準を通る不透明度 (92%) にしてある。 同じ理由でアイコンの色も固定していない。クイックスロットのグリフは白で決め打ちされていて、 ライトテーマで 1.11:1 と測れた — いまはラベルとまったく同じように、載っているパネルに従う。 2つの検査、2つの守備範囲。 check_contrast.py はテーマファイルを読む。 スキンが実行中に混ぜる色（チップ、スロット）は、Godot の中で走るテストスイートの skin contrast の節が測る。","",-1],[21,"names","アイコンは名前で呼ぶ",0,"ウィジェットは絵を持たない。名前を尋ねるだけで、何を描くかは使用中のアイコンセットが決める — セットを替えれば、コードを一行も触らずにすべてのアイコンが替わる。 GoUi.icons() が使用中のセットだ。描けない名前は場所を保つ空の箱になり、デバッグビルドでは警告が出る。アイコンが一つ欠けても行がずれない。","GoStyle.icon_button(GoIconSet.SETTINGS, open_settings) # a button slot.icon_name = GoGameIcons.BACKPACK # a quick slot var mark := GoUi.icons().node(&\"cloud_rain\", 24) # a bare Control, any size",-1],[21,"catalog","アイコンを探す",0,"gohud に入っている絵のすべて。名前や見た目で検索し、セットやグループで絞り込み、アイコンを選んで名前をコピーする。 アイコンを検索 グループすべてのグループ すべて 1,287 デフォルト 84 ゲーム 187 ライブラリ 1,000 中世 16 もっと見る 名前と検索語はどの言語でも英語のまま — コードに打つ文字だからだ。","",-1],[21,"sets","四つのセット、探し方は一つ",0,"どのセットも同じ呼び出しに答える。大きなセットは使用中のセットの上に足して使う。 セット 名前 定数 有効にする デフォルト 84 GoIconSet 常に有効 中世 彫刻風 16 枚 — GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) ゲーム 187 GoGameIcons GoUi.add_icons(GoGameIcons.icon_set()) ライブラリ 1,000 GoIconLibrary GoUi.add_icons(GoIconLibrary.icon_set()) ライブラリはゲームセットへ、ゲームセットはデフォルトセットへフォールバックするので、一行で 1,271 個の名前が描ける。セットは絵をパスで持ち、その名前を初めて描くときにファイルを読む — ライブラリを足しても 1,000 枚のテクスチャではなく、パスの表を一つ読むだけだ（デスクトップで約 30 ms）。 パスは文字列であって依存関係ではない。リソースを選んでエクスポートするなら addons/gohud/icons/ を含める。既定の「すべてのリソースをエクスポート」なら何もしなくてよい。","GoUi.add_icons(GoIconLibrary.icon_set()) # the library — and the game set under it GoUi.add_icons(GoGameIcons.icon_set()) # or the game set alone",-1],[21,"resolution","名前を探す順序",0,"どのセットも同じ順序に従う。だから、どの絵が勝つか前もって分かる。 まずすべてのセットの自前の絵 — 使用中のセット、次に足したセット、次にそれらのフォールバックを一段ずつ見る。自前の絵とは、テクスチャ・パス・アイコンフォントのグリフだ。 誰も描けなければ別名を見る: gear は settings へ、x は close へ。たどるのは一度だけ。 それでもなければ、場所を保つ空の箱。 中世プリセットにライブラリを足しても彫刻風の剣がそのまま残るのは、この順序のためだ — 中世セットの自前の絵が、誰のフォールバックよりも先に見つかる。","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) GoUi.add_icons(GoIconLibrary.icon_set()) GoUi.icons().texture(&\"sword\") # the medieval engraving — its own drawing comes first GoUi.icons().texture(&\"rocket\") # from the game set GoUi.icons().canonical(&\"gear\") # &\"settings\" — an alias",-1],[21,"swap","プリセット、自分のセット、足したセット",0,"何を描くかは三か所で決まる。 呼び出し すること GoUi.use_preset(…) テーマ・スキン・アイコンセットを一度に替える。config.icons は空にし、config.extra_icons は残す。 GoUi.config.icons = my_set プリセットのアイコンセットを自分のセットに替える。 GoUi.add_icons(set) 使用中のセットの次に見るセットを足す。プリセットを替えても残る。","",-1],[21,"custom","自分の絵を入れる",0,"名前をいくつか上書きする、フォルダーを丸ごと足す、アイコンフォントをつなぐ — 呼び出すコードはそのままだ。 24×24 のグリッドに白い線で描く。色は modulate で付くが、これは暗くすることしかできない — 黒く描いた絵はどのテーマでも黒いままだ。 SVG は DPITexture としてインポートする。そうすれば 64 dp のインベントリ枠でもくっきり見える。 アイコンは右から左へ書く言語でも反転しない。向きが変わるのは back と forward だけで、それは名前で選ぶ。 アイコンフォントも使える: font と codepoints を埋める。ほかは何も変わらない。","# Override a few names — everything else still comes from the set in use var mine := GoIconSet.new() mine.fallback = GoUi.icons() mine.textures = {GoIconSet.CLOSE: preload(\"res://art/close.svg\")} GoUi.config.icons = mine # A folder of drawings — file name = icon name, each read when first drawn GoUi.config.icons = GoIconSet.from_folder(\"res://art/icons\", GoUi.icons())",-1],[21,"naming","名前・グループ・検索",0,"同梱セットが守る規則と、名前を探す呼び出し。 lower_snake_case で、描いたものを先に、状態を後ろに付ける: volume_off, battery_charging, arrow_bar_left。 グループの接頭辞は付けない。グループはデータなので、どこに分類しても名前は変わらない。 ライブラリの名前は Tabler の名前のハイフンを下線に替えたもの: tabler.io の cloud-rain はここでは cloud_rain。gohud にすでにあった絵の Tabler 名は、別名としてその絵に届く（shopping_cart → cart）。 同じ意味の別の語は別名であって、二枚目の絵ではない。","",-1],[21,"search","search()",1,"","var icons := GoUi.icons() icons.search(\"arrow left\", 5) # best matches first: back, arrow_bar_left … icons.search(\"rain\") # cloud_rain, then drawings tagged \"rain\"",184],[21,"group-names-names-in-group","group_names() · names_in_group()",1,"","icons.group_names() # every group key, in lookup order icons.names_in_group(&\"weather\") # one group, in display order — every set's share of it icons.group_title(&\"weather\") # \"Weather & sky\"",184],[21,"canonical-has-icon","canonical() · has_icon()",1,"","icons.canonical(&\"gear\") # &\"settings\" icons.canonical(&\"treasure_chest\") # &\"chest\" — Tabler's name for a game drawing icons.has_icon(&\"cloud_rain\") # true once the library is added — nothing is loaded to answer",184],[21,"license","絵の出典",0,"すべて MIT。告知は THIRD_PARTY_NOTICES.md として ZIP に同梱される。 セット 出典 ライセンス デフォルト gohud のために描いた MIT 中世 gohud のために描いた MIT ゲーム 171 個は Tabler Icons 3.46.0、16 個は gohud のために描いた MIT ライブラリ Tabler Icons 3.46.0 MIT 他人のアイコンをつなぐなら、その出典を GoIconSet.attribution に書く — そして商用のアイコンフォントは、公開するフォークではなく自分のゲームの中にだけ置く。","",-1]]};
